"""Independent timing/interpolation checks for the bounded SMIL profile."""

from __future__ import annotations

import json
import math
from pathlib import Path
import subprocess
import tempfile
import unittest


ROOT = Path(__file__).resolve().parents[2]
FIXTURES = ROOT / "tests" / "anim" / "fixtures"
CLI = ROOT / "build" / "mac-debug" / "bin" / "animation_eval_cli"
WORKBENCH = ROOT / "build" / "mac-debug" / "bin" / "svgworkbench"


def cubic(t: float, first: float, second: float) -> float:
    inverse = 1.0 - t
    return 3 * inverse * inverse * t * first + 3 * inverse * t * t * second + t**3


def spline(progress: float, points: tuple[float, float, float, float]) -> float:
    low, high = 0.0, 1.0
    for _ in range(60):
        parameter = (low + high) / 2
        if cubic(parameter, points[0], points[2]) < progress:
            low = parameter
        else:
            high = parameter
    return cubic((low + high) / 2, points[1], points[3])


def reference_value(
    seconds: float,
    values: list[float],
    duration: float,
    key_times: list[float],
    calc_mode: str = "linear",
    spline_points: tuple[float, float, float, float] | None = None,
    repeat_count: float = 1.0,
    freeze: bool = False,
) -> float | None:
    if seconds < 0 or duration <= 0:
        raise ValueError("invalid reference time")
    elapsed = seconds
    active_duration = duration * repeat_count
    if elapsed >= active_duration:
        if not freeze:
            return None
        remainder = active_duration % duration
        progress = 1.0 if remainder == 0 else remainder / duration
    else:
        progress = (elapsed % duration) / duration

    right = 1
    while right + 1 < len(key_times) and progress >= key_times[right]:
        right += 1
    left = right - 1
    local = (progress - key_times[left]) / (key_times[right] - key_times[left])
    if calc_mode == "discrete":
        return values[left]
    if calc_mode == "spline":
        if spline_points is None:
            raise ValueError("spline controls are required")
        local = spline(local, spline_points)
    return values[left] + (values[right] - values[left]) * local


def cli_tracks(fixture: str, seconds: float) -> dict:
    result = subprocess.run(
        [str(CLI), str(FIXTURES / fixture), f"{seconds:.17g}"],
        check=True,
        capture_output=True,
        text=True,
    )
    return json.loads(result.stdout)


class AnimationReferenceTests(unittest.TestCase):
    def test_authored_fixture_inventory(self) -> None:
        fixtures = sorted(FIXTURES.glob("*.svg"))
        self.assertGreaterEqual(len(fixtures), 15)
        self.assertTrue(all(path.read_text(encoding="utf-8").startswith("<svg") for path in fixtures))

    def test_linear_opacity_matches_python_at_sampled_times(self) -> None:
        values = [1.0, 0.2, 1.0]
        key_times = [0.0, 0.5, 1.0]
        for sample in range(100):
            seconds = sample * 0.02
            expected = reference_value(seconds, values, 1.0, key_times,
                                       repeat_count=math.inf)
            actual = cli_tracks("loader-opacity.svg", seconds)["tracks"][0]
            self.assertTrue(actual["active"])
            self.assertAlmostEqual(actual["sample"]["value"], expected, places=10)

    def test_spline_and_discrete_match_python(self) -> None:
        spline_values = [0.0, 1.0]
        for sample in range(1, 50):
            seconds = sample / 50
            expected = reference_value(seconds, spline_values, 1.0, [0.0, 1.0],
                calc_mode="spline", spline_points=(0.42, 0.0, 0.58, 1.0))
            actual = cli_tracks("spline-opacity.svg", seconds)["tracks"][0]
            self.assertAlmostEqual(actual["sample"]["value"], expected, delta=1e-8)
        discrete = cli_tracks("discrete-opacity.svg", 0.75)["tracks"][0]
        self.assertEqual(discrete["sample"]["value"], 0.2)

    def test_syncbase_fixture_lists_both_tracks(self) -> None:
        result = cli_tracks("repeat-wave.svg", 5.0)
        self.assertEqual([item["attribute"] for item in result["tracks"]],
                         ["x", "opacity"])
        self.assertTrue(result["tracks"][0]["active"])
        self.assertTrue(result["tracks"][1]["active"])

    def test_render_frame_accepts_explicit_time(self) -> None:
        with tempfile.TemporaryDirectory(prefix="anim-cli-") as directory:
            output = Path(directory) / "frame.ppm"
            result = subprocess.run(
                [str(WORKBENCH), "--render-frame", str(FIXTURES / "slide-x.svg"),
                 "--size", "48x16", "--out", str(output), "--time", "1"],
                cwd=ROOT,
                capture_output=True,
                text=True,
                timeout=20,
                check=False,
            )
            self.assertEqual(result.returncode, 0, result.stderr)
            self.assertTrue(output.is_file())
            self.assertTrue(output.read_bytes().startswith(b"P6\n48 16\n255\n"))

    def test_render_animation_writes_bounded_ppm_sequence(self) -> None:
        with tempfile.TemporaryDirectory(prefix="anim-sequence-") as directory:
            output = Path(directory) / "frames"
            output.mkdir()
            result = subprocess.run(
                [str(WORKBENCH), "--render-animation", str(FIXTURES / "slide-x.svg"),
                 "--fps", "2", "--duration", "1", "--out", str(output)],
                cwd=ROOT, capture_output=True, text=True, timeout=30, check=False,
            )
            self.assertEqual(result.returncode, 0, result.stderr)
            frames = sorted(output.glob("frame-*.ppm"))
            self.assertEqual(len(frames), 2)
            self.assertTrue(all(frame.read_bytes().startswith(b"P6\n48 16\n255\n")
                                for frame in frames))

    def test_render_animation_rejects_more_than_300_frames(self) -> None:
        with tempfile.TemporaryDirectory(prefix="anim-sequence-limit-") as directory:
            result = subprocess.run(
                [str(WORKBENCH), "--render-animation", str(FIXTURES / "slide-x.svg"),
                 "--fps", "60", "--duration", "6", "--out", directory],
                cwd=ROOT, capture_output=True, text=True, timeout=10, check=False,
            )
            self.assertEqual(result.returncode, 2)
            self.assertIn("at most 300 frames", result.stderr)


if __name__ == "__main__":
    unittest.main()
#include "base.h"
#include "svg/animation/animation.h"
#include "xml_tokenizer.h"

#include <errno.h>
#include <math.h>
#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define CLI_MAX_SOURCE (16U * 1024U * 1024U)

static bool read_source(const char *path, uint8_t **out, size_t *length)
{
    FILE *file = fopen(path, "rb");
    if (file == NULL) return false;
    bool okay = fseek(file, 0L, SEEK_END) == 0;
    long file_length = okay ? ftell(file) : -1L;
    if (file_length <= 0L || (unsigned long)file_length > CLI_MAX_SOURCE ||
        fseek(file, 0L, SEEK_SET) != 0) okay = false;
    uint8_t *bytes = okay ? malloc((size_t)file_length) : NULL;
    if (bytes == NULL) okay = false;
    if (okay) okay = fread(bytes, 1U, (size_t)file_length, file) == (size_t)file_length;
    if (fclose(file) != 0) okay = false;
    if (!okay) {
        free(bytes);
        return false;
    }
    *out = bytes;
    *length = (size_t)file_length;
    return true;
}

static bool parse_time(const char *text, double *out)
{
    if (text == NULL || text[0] == '\0') return false;
    errno = 0;
    char *end = NULL;
    double value = strtod(text, &end);
    if (errno != 0 || end == text || *end != '\0' || !isfinite(value) ||
        value < 0.0 || value > SVG_ANIM_MAX_TIMELINE_SECONDS) return false;
    *out = value;
    return true;
}

static bool print_value(const svg_anim_value *value)
{
    if (value->kind == SVG_ANIM_VALUE_NUMBER)
        return printf("{\"kind\":\"number\",\"value\":%.17g}",
                      value->number[0]) >= 0;
    if (value->kind == SVG_ANIM_VALUE_COLOR)
        return printf("{\"kind\":\"color\",\"value\":[%u,%u,%u,%u]}",
            value->rgba[0], value->rgba[1], value->rgba[2], value->rgba[3]) >= 0;
    if (value->kind == SVG_ANIM_VALUE_TRANSFORM)
        return printf("{\"kind\":\"transform\",\"value\":[%.17g,%.17g,%.17g,%.17g]}",
            value->number[0], value->number[1], value->number[2], value->number[3]) >= 0;
    if (value->kind == SVG_ANIM_VALUE_MOTION)
        return printf("{\"kind\":\"motion\",\"value\":[%.17g,%.17g,%.17g]}",
            value->number[0], value->number[1], value->number[2]) >= 0;
    return fputs("{\"kind\":\"path\"}", stdout) >= 0;
}

int main(int argc, char **argv)
{
    if (argc != 3) return 2;
    double seconds = 0.0;
    uint8_t *source_memory = NULL;
    size_t source_length = 0U;
    if (!parse_time(argv[2], &seconds) ||
        !read_source(argv[1], &source_memory, &source_length)) return 2;
    base_bytes source = {source_memory, source_length};
    size_t token_capacity = source_length / 2U + 2U;
    if (token_capacity > SIZE_MAX / sizeof(svg_xml_token)) {
        free(source_memory);
        return 2;
    }
    svg_xml_token *tokens = calloc(token_capacity, sizeof(*tokens));
    if (tokens == NULL) {
        free(source_memory);
        return 2;
    }
    svg_xml_result xml = svg_xml_tokenize(source, svg_xml_default_options(),
                                          tokens, token_capacity);
    svg_anim_document document = {0};
    svg_anim_overlay overlay = {0};
    size_t error_offset = 0U;
    bool okay = xml.diagnostic.category == SVG_XML_ERROR_NONE &&
        svg_anim_parse(source, tokens, xml.token_count, &document, &error_offset) &&
        svg_anim_eval(&document, seconds, &overlay);
    if (okay) {
        okay = printf("{\"time\":%.17g,\"tracks\":[", seconds) >= 0;
        for (size_t index = 0U; okay && index < overlay.count; ++index) {
            const svg_anim_track *track = &document.tracks[index];
            const svg_anim_overlay_item *item = &overlay.items[index];
            if (index > 0U) okay = fputc(',', stdout) >= 0;
            if (okay) okay = printf("{\"attribute\":\"%s\",\"active\":%s,\"iteration\":%zu,\"sample\":",
                svg_anim_attribute_name(track->attribute), item->active ? "true" : "false",
                item->iteration) >= 0;
            if (okay && item->active) okay = print_value(&item->value);
            else if (okay) okay = fputs("null", stdout) >= 0;
            if (okay) okay = fputc('}', stdout) >= 0;
        }
        if (okay) okay = printf("],\"diagnostic_count\":%zu}\n",
                                  document.diagnostic_count) >= 0;
    }
    svg_anim_overlay_destroy(&overlay);
    svg_anim_document_destroy(&document);
    free(tokens);
    free(source_memory);
    return okay ? 0 : 1;
}

//! Bounded, source-preserving SMIL animation parsing and evaluation.
//!
//! Source is borrowed for the lifetime of the document. All parsed track data is
//! owned; raw values and XML locations remain checked byte spans into that
//! source. No parser or evaluator operation rewrites the document.

#![forbid(unsafe_code)]

mod eval;
mod motion;
mod parse;
mod parse_values;

use vexel_xml::XmlSpan;

pub const MAX_TRACKS: usize = 128;
pub const MAX_VALUES: usize = 256;
pub const MAX_DIAGNOSTICS: usize = 128;
pub const MAX_TIMELINE_SECONDS: f64 = 3600.0;

#[derive(Debug, Clone, Copy, PartialEq, Eq)]
#[repr(u8)]
pub enum Attribute {
    X,
    Y,
    Width,
    Height,
    Cx,
    Cy,
    R,
    Rx,
    Ry,
    Opacity,
    FillOpacity,
    StrokeOpacity,
    Fill,
    Stroke,
    StrokeWidth,
    StrokeDashoffset,
    D,
    Transform,
    Motion,
}
impl Attribute {
    pub const fn name(self) -> &'static str {
        match self {
            Self::X => "x",
            Self::Y => "y",
            Self::Width => "width",
            Self::Height => "height",
            Self::Cx => "cx",
            Self::Cy => "cy",
            Self::R => "r",
            Self::Rx => "rx",
            Self::Ry => "ry",
            Self::Opacity => "opacity",
            Self::FillOpacity => "fill-opacity",
            Self::StrokeOpacity => "stroke-opacity",
            Self::Fill => "fill",
            Self::Stroke => "stroke",
            Self::StrokeWidth => "stroke-width",
            Self::StrokeDashoffset => "stroke-dashoffset",
            Self::D => "d",
            Self::Transform => "transform",
            Self::Motion => "motion",
        }
    }
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum Kind {
    Animate,
    Transform,
    Set,
    Motion,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum ValueKind {
    Number,
    Color,
    Transform,
    Motion,
    Path,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum CalcMode {
    Linear,
    Spline,
    Discrete,
    Paced,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum FillMode {
    Remove,
    Freeze,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum TransformType {
    Translate,
    Scale,
    Rotate,
    SkewX,
    SkewY,
}
#[derive(Debug, Clone, Copy, PartialEq, Eq)]
pub enum DiagnosticKind {
    UnsupportedElement,
    UnsupportedAttribute,
    UnsupportedTiming,
    UnsupportedComposition,
    UnsupportedPath,
    CssAnimation,
    InvalidTrack,
}
impl DiagnosticKind {
    pub const fn name(self) -> &'static str {
        match self {
            Self::UnsupportedElement => "unsupported-element",
            Self::UnsupportedAttribute => "unsupported-attribute",
            Self::UnsupportedTiming => "unsupported-timing",
            Self::UnsupportedComposition => "unsupported-composition",
            Self::UnsupportedPath => "unsupported-path",
            Self::CssAnimation => "css-animation",
            Self::InvalidTrack => "invalid-track",
        }
    }
}

