fn parse_track(
    src: &[u8],
    tokens: &[XmlToken],
    i: usize,
    parent: usize,
    d: &mut Document<'_>,
    allocation_failed: &mut bool,
) -> Option<Track> {
    let tag = &tokens[i];
    let name = span(src, tag.local_name)?;
    let mut t = Track::default();
    t.id = attr0(src, tokens, i, b"id");
    t.target = element_span(tokens, parent)?;
    t.element = element_span(tokens, i)?;
    if tag.prefix.length != 0 {
        diagnostic(d, DiagnosticKind::UnsupportedElement, tag.name.offset);
        return None;
    }
    t.kind = match name {
        b"animate" => Kind::Animate,
        b"animateTransform" => Kind::Transform,
        b"set" => Kind::Set,
        b"animateMotion" => Kind::Motion,
        _ => {
            diagnostic(d, DiagnosticKind::UnsupportedElement, tag.name.offset);
            return None;
        }
    };
    let an = attr0(src, tokens, i, b"attributeName");
    if t.kind == Kind::Motion {
        t.attribute = Attribute::Motion
    } else {
        if an.length == 0 {
            diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
            return None;
        }
        let (a, tr) = attr_kind(src, an);
        t.attribute = a;
        if t.kind == Kind::Transform {
            if !tr {
                diagnostic(d, DiagnosticKind::UnsupportedAttribute, an.offset);
                return None;
            }
        } else if tr || a == Attribute::Motion {
            diagnostic(d, DiagnosticKind::UnsupportedAttribute, an.offset);
            return None;
        }
    }
    let ttspan = attr0(src, tokens, i, b"type");
    if t.kind == Kind::Transform {
        if ttspan.length == 0 || ttspan.length >= 16 {
            diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
            return None;
        }
        let b = span(src, ttspan)?;
        t.transform_type = match b {
            b"translate" => TransformType::Translate,
            b"scale" => TransformType::Scale,
            b"rotate" => TransformType::Rotate,
            b"skewX" => TransformType::SkewX,
            b"skewY" => TransformType::SkewY,
            _ => {
                diagnostic(d, DiagnosticKind::UnsupportedAttribute, ttspan.offset);
                return None;
            }
        }
    }
    let at = attr0(src, tokens, i, b"attributeType");
    if at.length > 0 && !eq(src, at, b"XML") {
        diagnostic(d, DiagnosticKind::UnsupportedAttribute, at.offset);
        return None;
    }
    let cm = attr0(src, tokens, i, b"calcMode");
    t.calc_mode = match if cm.length == 0 {
        b"linear".as_slice()
    } else {
        span(src, cm)?
    } {
        b"linear" => CalcMode::Linear,
        b"discrete" => CalcMode::Discrete,
        b"spline" => CalcMode::Spline,
        b"paced" => CalcMode::Paced,
        _ => {
            diagnostic(d, DiagnosticKind::UnsupportedAttribute, cm.offset);
            return None;
        }
    };
    let fill = attr0(src, tokens, i, b"fill");
    t.fill_mode = match if fill.length == 0 {
        b"remove".as_slice()
    } else {
        span(src, fill)?
    } {
        b"remove" => FillMode::Remove,
        b"freeze" => FillMode::Freeze,
        _ => {
            diagnostic(d, DiagnosticKind::UnsupportedAttribute, fill.offset);
            return None;
        }
    };
    let add = attr0(src, tokens, i, b"additive");
    if add.length > 0 && !eq(src, add, b"replace") {
        if eq(src, add, b"sum") {
            t.additive_sum = true
        } else {
            diagnostic(d, DiagnosticKind::UnsupportedComposition, add.offset);
            return None;
        }
    }
    let acc = attr0(src, tokens, i, b"accumulate");
    if acc.length > 0 && !eq(src, acc, b"none") {
        if eq(src, acc, b"sum") {
            t.accumulate = true
        } else {
            diagnostic(d, DiagnosticKind::UnsupportedComposition, acc.offset);
            return None;
        }
    }
    if (t.kind == Kind::Motion && (t.additive_sum || t.accumulate))
        || (t.kind == Kind::Transform && t.accumulate)
        || (t.attribute == Attribute::D && (t.additive_sum || t.accumulate))
    {
        diagnostic(d, DiagnosticKind::UnsupportedComposition, tag.name.offset);
        return None;
    }
    let begin = attr0(src, tokens, i, b"begin");
    if begin.length > 0 && !sync_time(src, begin, &mut t, true) {
        diagnostic(d, DiagnosticKind::UnsupportedTiming, begin.offset);
        return None;
    }
    let end = attr0(src, tokens, i, b"end");
    if end.length > 0 && !sync_time(src, end, &mut t, false) {
        diagnostic(d, DiagnosticKind::UnsupportedTiming, end.offset);
        return None;
    }
    let dur = attr0(src, tokens, i, b"dur");
    if dur.length == 0 && t.kind != Kind::Set {
        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
        return None;
    }
    if eq(src, dur, b"indefinite") {
        t.duration_indefinite = true
    } else if dur.length > 0 {
        t.duration_seconds = match time(src, dur) {
            Some(n) => n,
            None => {
                diagnostic(d, DiagnosticKind::UnsupportedTiming, dur.offset);
                return None;
            }
        }
    }
    if !t.duration_indefinite && t.kind != Kind::Set && t.duration_seconds <= 0. {
        diagnostic(d, DiagnosticKind::InvalidTrack, dur.offset);
        return None;
    }
    if t.kind == Kind::Set && dur.length == 0 {
        t.duration_indefinite = true
    }
    let rep = attr0(src, tokens, i, b"repeatCount");
    if eq(src, rep, b"indefinite") {
        t.repeat_indefinite = true;
        t.repeat_count = f64::INFINITY
    } else if rep.length > 0 {
        t.repeat_count = match number(src, rep) {
            Some(n) if n > 0. && n <= 100000. => n,
            _ => {
                diagnostic(d, DiagnosticKind::UnsupportedTiming, tag.name.offset);
                return None;
            }
        }
    }
    if t.kind == Kind::Set {
        t.repeat_count = 1.
    }
    let rd = attr0(src, tokens, i, b"repeatDur");
    if eq(src, rd, b"indefinite") {
        t.repeat_duration_indefinite = true
    } else if rd.length > 0 {
        t.repeat_duration = match time(src, rd) {
            Some(n) => n,
            None => {
                diagnostic(d, DiagnosticKind::UnsupportedTiming, rd.offset);
                return None;
            }
        }
    }
    t.base_value = base_value(src, tokens, parent, t.attribute, t.kind, t.transform_type)?;
    let vals = attr0(src, tokens, i, b"values");
    let from = attr0(src, tokens, i, b"from");
    let to = attr0(src, tokens, i, b"to");
    let by = attr0(src, tokens, i, b"by");
    if vals.length > 0 && (from.length > 0 || to.length > 0 || by.length > 0) {
        diagnostic(d, DiagnosticKind::InvalidTrack, vals.offset);
        return None;
    }
    let mut pieces = Vec::new();
    if pieces.try_reserve_exact(MAX_VALUES).is_err() {
        *allocation_failed = true;
        return None;
    }
    let mut implicit = false;
    let mut by_value = false;
    if t.kind == Kind::Motion {
        let path = resolve_motion_path(src, tokens, i)
            .filter(|p| parse_motion(src, *p, &mut t, allocation_failed));
        if path.is_none() {
            diagnostic(d, DiagnosticKind::UnsupportedPath, tag.name.offset);
            return None;
        }
        let rot = attr0(src, tokens, i, b"rotate");
        if eq(src, rot, b"auto") {
            t.motion_rotate_auto = true
        } else if eq(src, rot, b"auto-reverse") {
            t.motion_rotate_auto = true;
            t.motion_rotate_reverse = true
        } else if rot.length > 0 {
            t.motion_fixed_rotation = match number(src, rot) {
                Some(n) => n,
                _ => {
                    diagnostic(d, DiagnosticKind::UnsupportedAttribute, rot.offset);
                    return None;
                }
            }
        }
        pieces.push(path.unwrap());
    } else if vals.length > 0 {
        pieces = match split(src, vals, allocation_failed) {
            Some(p) => p,
            None => {
                diagnostic(d, DiagnosticKind::InvalidTrack, vals.offset);
                return None;
            }
        }
    } else if t.kind == Kind::Set {
        if to.length == 0 {
            diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
            return None;
        }
        pieces.push(to)
    } else if from.length > 0 && to.length > 0 {
        pieces.extend([from, to])
    } else if to.length > 0 {
        implicit = true;
        pieces.push(to)
    } else if by.length > 0 {
        implicit = true;
        by_value = true;
        pieces.push(by)
    } else {
        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
        return None;
    }
    if pieces.is_empty() || pieces.len() > MAX_VALUES {
        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
        return None;
    }
    let source_count = pieces.len();
    if implicit && source_count >= MAX_VALUES {
        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
        return None;
    }
    let count = source_count + usize::from(implicit);
    if t.keys.try_reserve_exact(count).is_err() {
        *allocation_failed = true;
        return None;
    }
    if implicit {
        t.keys.push(Keyframe {
            time: 0.,
            value: t.base_value,
            source: t.base_value.raw,
        })
    }
    for (j, p) in pieces.iter().enumerate() {
        let mut v = match parse_value(src, *p, t.attribute, t.kind, t.transform_type) {
            Some(v) => v,
            None => {
                diagnostic(
                    d,
                    if t.attribute == Attribute::D {
                        DiagnosticKind::UnsupportedPath
                    } else {
                        DiagnosticKind::InvalidTrack
                    },
                    p.offset,
                );
                return None;
            }
        };
        if by_value {
            if v.kind != ValueKind::Number || t.base_value.kind != ValueKind::Number {
                diagnostic(d, DiagnosticKind::UnsupportedComposition, p.offset);
                return None;
            }
            v.number[0] += t.base_value.number[0]
        }
        let k = j + usize::from(implicit);
        t.keys.push(Keyframe {
            time: if count == 1 {
                0.
            } else {
                k as f64 / (count - 1) as f64
            },
            value: v,
            source: *p,
        })
    }
    if t.kind == Kind::Animate && t.attribute == Attribute::D {
        let base = attr0(src, tokens, parent, b"d");
        if base.length == 0 {
            diagnostic(d, DiagnosticKind::UnsupportedPath, tag.name.offset);
            return None;
        }
        for key in &t.keys {
            if !paths_match(src, base, key.value.raw) {
                diagnostic(d, DiagnosticKind::UnsupportedPath, key.value.raw.offset);
                return None;
            }
        }
    }
    let kt = attr0(src, tokens, i, b"keyTimes");
    if kt.length > 0 {
        let ts = match split(src, kt, allocation_failed) {
            Some(x) => x,
            None => {
                diagnostic(d, DiagnosticKind::InvalidTrack, kt.offset);
                return None;
            }
        };
        if ts.len() != t.keys.len() {
            diagnostic(d, DiagnosticKind::InvalidTrack, kt.offset);
            return None;
        }
        let mut prev = -1.;
        for (k, s) in t.keys.iter_mut().zip(ts) {
            let n = number(src, s).filter(|n| *n >= 0. && *n <= 1. && *n > prev);
            if let Some(n) = n {
                k.time = n;
                prev = n
            } else {
                diagnostic(d, DiagnosticKind::InvalidTrack, kt.offset);
                return None;
            }
        }
        if t.keys[0].time != 0. || (t.kind != Kind::Set && t.keys.last()?.time != 1.) {
            diagnostic(d, DiagnosticKind::InvalidTrack, kt.offset);
            return None;
        }
        if t.calc_mode == CalcMode::Paced {
            diagnostic(d, DiagnosticKind::UnsupportedAttribute, kt.offset);
            return None;
        }
    }
    let spl = attr0(src, tokens, i, b"keySplines");
    if t.calc_mode != CalcMode::Spline {
        if spl.length > 0 {
            diagnostic(d, DiagnosticKind::InvalidTrack, spl.offset);
            return None;
        }
    } else {
        let ss = match split(src, spl, allocation_failed) {
            Some(x) => x,
            None => {
                diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
                return None;
            }
        };
        if ss.len() != t.keys.len().saturating_sub(1) {
            diagnostic(d, DiagnosticKind::InvalidTrack, spl.offset);
            return None;
        }
        if t.splines.try_reserve_exact(ss.len()).is_err() {
            *allocation_failed = true;
            return None;
        }
        for s in ss {
            let b = span(src, s)?;
            if b.len() >= 256 {
                return None;
            }
            let (vals, count) = number_list(b, 4)?;
            if count != 4 || vals.iter().any(|v| !v.is_finite() || *v < 0. || *v > 1.) {
                diagnostic(d, DiagnosticKind::InvalidTrack, spl.offset);
                return None;
            }
            t.splines.push([vals[0], vals[1], vals[2], vals[3]])
        }
    }
    Some(t)
}

pub fn parse<'a>(source: &'a [u8], tokens: &[XmlToken]) -> Result<Document<'a>, ParseError> {
    let mut d = Document {
        source,
        tracks: Vec::new(),
        diagnostics: Vec::new(),
    };
    d.tracks
        .try_reserve_exact(MAX_TRACKS)
        .map_err(|_| ParseError::Allocation)?;
    d.diagnostics
        .try_reserve_exact(MAX_DIAGNOSTICS)
        .map_err(|_| ParseError::Allocation)?;
    let mut allocation_failed = false;
    for (i, t) in tokens.iter().enumerate() {
        if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement) {
            continue;
        }
        let name = span(source, t.local_name).unwrap_or_default();
        if t.prefix.length == 0 && name == b"style" {
            for x in tokens
                .iter()
                .skip(i + 1)
                .take_while(|x| !(x.kind == TokenKind::EndElement && x.depth == t.depth))
            {
                if x.kind == TokenKind::Text {
                    if let Some(b) = span(source, x.value) {
                        if [b"@keyframes".as_slice(), b"animation:", b"transition:"]
                            .iter()
                            .any(|n| b.windows(n.len()).any(|w| w == *n))
                        {
                            diagnostic(&mut d, DiagnosticKind::CssAnimation, x.value.offset)
                        }
                    }
                }
            }
        }
        if t.prefix.length != 0
            || !matches!(
                name,
                b"animate" | b"animateTransform" | b"set" | b"animateMotion" | b"animateColor"
            )
        {
            continue;
        }
        if d.tracks.len() >= MAX_TRACKS {
            return Err(ParseError::TrackLimit {
                offset: t.name.offset,
            });
        }
        let parent = (0..i).rev().find(|&j| {
            matches!(
                tokens[j].kind,
                TokenKind::StartElement | TokenKind::EmptyElement
            ) && tokens[j].depth + 1 == t.depth
        });
        let Some(parent) = parent else {
            diagnostic(&mut d, DiagnosticKind::InvalidTrack, t.name.offset);
            continue;
        };
        if let Some(track) = parse_track(source, tokens, i, parent, &mut d, &mut allocation_failed)
        {
            d.tracks.push(track)
        }
        if allocation_failed {
            return Err(ParseError::Allocation);
        }
    }
    // Resolve syncbase identifiers only after every supported track has been collected.
    for i in 0..d.tracks.len() {
        for begin in [true, false] {
            let id = if begin {
                d.tracks[i].begin_sync_id
            } else {
                d.tracks[i].end_sync_id
            };
            let Some(id) = id else { continue };
            let needle = span(source, id).unwrap_or_default();
            let mut found = None;
            let mut match_count = 0;
            for (j, track) in d.tracks.iter().enumerate() {
                if track.id.length > 0 && span(source, track.id) == Some(needle) {
                    found = Some(j);
                    match_count += 1;
                }
            }
            if match_count != 1 {
                diagnostic(&mut d, DiagnosticKind::UnsupportedTiming, id.offset);
                d.tracks[i].supported = false
            } else if begin {
                d.tracks[i].begin_sync_track = found
            } else {
                d.tracks[i].end_sync_track = found
            }
        }
    }
    // Cycles are retained as unsupported timing and resolved by evaluator to inactive tracks.
    Ok(d)
}

use crate::*;
use vexel_xml::{TokenKind, XmlSpan, XmlToken};

pub(crate) const MAX_PATH_BYTES: usize = 64 * 1024;
pub(crate) const MAX_PATH_NUMBERS: usize = 4096;

pub(crate) fn span(source: &[u8], s: XmlSpan) -> Option<&[u8]> {
    s.slice(source)
}
pub(crate) fn eq(source: &[u8], s: XmlSpan, b: &[u8]) -> bool {
    span(source, s) == Some(b)
}
pub(crate) fn attr(source: &[u8], tokens: &[XmlToken], e: usize, name: &[u8]) -> Option<XmlSpan> {
    tokens.get(e)?;
    tokens
        .iter()
        .skip(e + 1)
        .take_while(|a| a.kind == TokenKind::Attribute)
        .find(|a| a.prefix.length == 0 && eq(source, a.local_name, name))
        .map(|a| a.value)
}
pub(crate) fn attr0(source: &[u8], tokens: &[XmlToken], e: usize, name: &[u8]) -> XmlSpan {
    attr(source, tokens, e, name).unwrap_or_default()
}
pub(crate) fn number(source: &[u8], s: XmlSpan) -> Option<f64> {
    let b = span(source, s)?;
    if b.is_empty() || b.len() >= 128 {
        return None;
    }
    let b = b.trim_ascii_start();
    let t = std::str::from_utf8(b).ok()?;
    let n = t.parse::<f64>().ok()?;
    n.is_finite().then_some(n)
}
pub(crate) fn time(source: &[u8], s: XmlSpan) -> Option<f64> {
    let b = span(source, s)?;
    if b.is_empty() || b.len() >= 128 {
        return None;
    }
    let (body, mul) = if b.ends_with(b"ms") {
        (&b[..b.len() - 2], 0.001)
    } else if b.ends_with(b"s") {
        (&b[..b.len() - 1], 1.0)
    } else {
        (b, 1.0)
    };
    let n = std::str::from_utf8(body.trim_ascii_start())
        .ok()?
        .parse::<f64>()
        .ok()?;
    let v = n * mul;
    if n.is_finite() && n >= 0.0 && v.is_finite() && v <= MAX_TIMELINE_SECONDS {
        Some(v)
    } else {
        None
    }
}
pub(crate) fn diagnostic(d: &mut Document<'_>, kind: DiagnosticKind, offset: usize) {
    if d.diagnostics.len() < MAX_DIAGNOSTICS {
        d.diagnostics.push(Diagnostic { kind, offset })
    }
}
pub(crate) fn element_span(tokens: &[XmlToken], i: usize) -> Option<XmlSpan> {
    let start = tokens.get(i)?.source.offset;
    let mut end = start.checked_add(tokens[i].source.length)?;
    if tokens[i].kind == TokenKind::StartElement {
        let depth = tokens[i].depth;
        let close = tokens
            .iter()
            .skip(i + 1)
            .find(|t| t.kind == TokenKind::EndElement && t.depth == depth)?;
        end = close.source.offset.checked_add(close.source.length)?;
    }
    Some(XmlSpan {
        offset: start,
        length: end.checked_sub(start)?,
    })
}
pub(crate) fn attr_kind(source: &[u8], s: XmlSpan) -> (Attribute, bool) {
    let b = span(source, s).unwrap_or_default();
    let a = match b {
        b"x" => Some(Attribute::X),
        b"y" => Some(Attribute::Y),
        b"width" => Some(Attribute::Width),
        b"height" => Some(Attribute::Height),
        b"cx" => Some(Attribute::Cx),
        b"cy" => Some(Attribute::Cy),
        b"r" => Some(Attribute::R),
        b"rx" => Some(Attribute::Rx),
        b"ry" => Some(Attribute::Ry),
        b"opacity" => Some(Attribute::Opacity),
        b"fill-opacity" => Some(Attribute::FillOpacity),
        b"stroke-opacity" => Some(Attribute::StrokeOpacity),
        b"fill" => Some(Attribute::Fill),
        b"stroke" => Some(Attribute::Stroke),
        b"stroke-width" => Some(Attribute::StrokeWidth),
        b"stroke-dashoffset" => Some(Attribute::StrokeDashoffset),
        b"d" => Some(Attribute::D),
        b"transform" => Some(Attribute::Transform),
        _ => None,
    };
    (a.unwrap_or(Attribute::Motion), b == b"transform")
}
pub(crate) fn color(source: &[u8], s: XmlSpan) -> Option<[u8; 4]> {
    let b = span(source, s)?;
    if b == b"none" {
        return Some([0; 4]);
    }
    if b.len() == 4 && b[0] == b'#' {
        let mut c = [0, 0, 0, 255];
        for i in 0..3 {
            c[i] = hex(b[i + 1])?.checked_mul(17)?
        }
        return Some(c);
    }
    if (b.len() == 7 || b.len() == 9) && b[0] == b'#' {
        let mut c = [0, 0, 0, 255];
        let n = if b.len() == 9 { 4 } else { 3 };
        for i in 0..n {
            c[i] = hex(b[1 + i * 2])?
                .checked_mul(16)?
                .checked_add(hex(b[2 + i * 2])?)?
        }
        return Some(c);
    }
    Some(match b {
        b"black" => [0, 0, 0, 255],
        b"white" => [255, 255, 255, 255],
        b"red" => [255, 0, 0, 255],
        b"green" => [0, 128, 0, 255],
        b"blue" => [0, 0, 255, 255],
        b"yellow" => [255, 255, 0, 255],
        b"cyan" => [0, 255, 255, 255],
        b"magenta" => [255, 0, 255, 255],
        b"gray" | b"grey" => [128, 128, 128, 255],
        b"transparent" => [0, 0, 0, 0],
        _ => return None,
    })
}
pub(crate) fn hex(b: u8) -> Option<u8> {
    match b {
        b'0'..=b'9' => Some(b - b'0'),
        b'a'..=b'f' => Some(b - b'a' + 10),
        b'A'..=b'F' => Some(b - b'A' + 10),
        _ => None,
    }
}
pub(crate) fn parse_value(
    source: &[u8],
    s: XmlSpan,
    a: Attribute,
    k: Kind,
    tt: TransformType,
) -> Option<Value> {
    let mut v = Value {
        raw: s,
        ..Value::default()
    };
    if k == Kind::Motion {
        v.kind = ValueKind::Motion;
        return Some(v);
    }
    if k == Kind::Transform {
        let b = span(source, s)?;
        if b.is_empty() || b.len() > 256 {
            return None;
        }
        let (vals, count) = number_list(b, 4)?;
        let (min, max) = match tt {
            TransformType::Rotate => (1, 3),
            TransformType::Translate | TransformType::Scale => (1, 2),
            _ => (1, 1),
        };
        if count < min || count > max {
            return None;
        }
        v.kind = ValueKind::Transform;
        v.number[..count].copy_from_slice(&vals[..count]);
        v.number[3] = count as f64;
        return Some(v);
    }
    if a == Attribute::D {
        v.kind = ValueKind::Path;
        return Some(v);
    }
    if matches!(a, Attribute::Fill | Attribute::Stroke) {
        v.kind = ValueKind::Color;
        v.rgba = color(source, s)?;
        return Some(v);
    }
    v.kind = ValueKind::Number;
    v.number[0] = number(source, s)?;
    Some(v)
}
pub(crate) fn number_list(bytes: &[u8], limit: usize) -> Option<([f64; 4], usize)> {
    let mut values = [0.0; 4];
    let mut count = 0;
    let mut pos = 0;
    while pos < bytes.len() {
        while bytes
            .get(pos)
            .is_some_and(|b| b.is_ascii_whitespace() || *b == b',')
        {
            pos += 1;
        }
        if pos == bytes.len() {
            break;
        }
        if count >= limit || count >= values.len() {
            return None;
        }
        let start = pos;
        if matches!(bytes.get(pos), Some(b'+' | b'-')) {
            pos += 1;
        }
        let mut digits = false;
        while bytes.get(pos).is_some_and(u8::is_ascii_digit) {
            digits = true;
            pos += 1;
        }
        if bytes.get(pos) == Some(&b'.') {
            pos += 1;
            while bytes.get(pos).is_some_and(u8::is_ascii_digit) {
                digits = true;
                pos += 1;
            }
        }
        if !digits {
            return None;
        }
        if matches!(bytes.get(pos), Some(b'e' | b'E')) {
            pos += 1;
            if matches!(bytes.get(pos), Some(b'+' | b'-')) {
                pos += 1;
            }
            let exp = pos;
            while bytes.get(pos).is_some_and(u8::is_ascii_digit) {
                pos += 1;
            }
            if exp == pos {
                return None;
            }
        }
        let value = std::str::from_utf8(&bytes[start..pos])
            .ok()?
            .parse::<f64>()
            .ok()?;
        if !value.is_finite() {
            return None;
        }
        values[count] = value;
        count += 1;
    }
    Some((values, count))
}
pub(crate) fn base_value(
    source: &[u8],
    tokens: &[XmlToken],
    target: usize,
    a: Attribute,
    k: Kind,
    tt: TransformType,
) -> Option<Value> {
    if k == Kind::Transform {
        let mut v = Value {
            kind: ValueKind::Transform,
            ..Value::default()
        };
        v.number[3] = match tt {
            TransformType::Scale => {
                v.number[0] = 1.;
                v.number[1] = 1.;
                2.
            }
            TransformType::Translate => 2.,
            _ => 1.,
        };
        return Some(v);
    }
    if k == Kind::Motion {
        return Some(Value {
            kind: ValueKind::Motion,
            ..Value::default()
        });
    }
    let Some(raw) = attr(source, tokens, target, a.name().as_bytes()) else {
        let mut v = Value::default();
        if matches!(a, Attribute::Fill | Attribute::Stroke) {
            v.kind = ValueKind::Color;
            if a == Attribute::Fill {
                v.rgba[3] = 255
            }
        } else if matches!(
            a,
            Attribute::Opacity | Attribute::FillOpacity | Attribute::StrokeOpacity
        ) {
            v.number[0] = 1.
        }
        return Some(v);
    };
    parse_value(source, raw, a, k, tt)
}
pub(crate) fn split(
    source: &[u8],
    s: XmlSpan,
    allocation_failed: &mut bool,
) -> Option<Vec<XmlSpan>> {
    let b = span(source, s)?;
    let count = b.iter().filter(|&&x| x == b';').count().checked_add(1)?;
    if count > MAX_VALUES {
        return None;
    }
    let mut out = Vec::new();
    if out.try_reserve_exact(count).is_err() {
        *allocation_failed = true;
        return None;
    }
    let mut start = 0;
    for i in 0..=b.len() {
        if i == b.len() || b[i] == b';' {
            let mut a = start;
            let mut z = i;
            while a < z && b" \t\r\n".contains(&b[a]) {
                a += 1
            }
            while z > a && b" \t\r\n".contains(&b[z - 1]) {
                z -= 1
            }
            if a == z || out.len() >= MAX_VALUES {
                return None;
            }
            out.push(XmlSpan {
                offset: s.offset.checked_add(a)?,
                length: z - a,
            });
            start = i.saturating_add(1)
        }
    }
    Some(out)
}
pub(crate) fn sync_time(src: &[u8], s: XmlSpan, t: &mut Track, is_begin: bool) -> bool {
    if eq(src, s, b"indefinite") {
        if is_begin {
            t.begin_indefinite = true
        } else {
            t.has_end = false
        }
        return true;
    }
    if let Some(v) = time(src, s) {
        if is_begin {
            t.begin_offset = v
        } else {
            t.end_seconds = v;
            t.has_end = true
        }
        return true;
    }
    let Some(b) = span(src, s) else { return false };
    let Some(dot) = b.iter().position(|&x| x == b'.') else {
        return false;
    };
    if dot == 0 || dot + 1 >= b.len() {
        return false;
    }
    let suffix_end = (dot + 1..b.len())
        .find(|&i| matches!(b[i], b'+' | b'-'))
        .unwrap_or(b.len());
    let suffix = &b[dot + 1..suffix_end];
    let sync_end = match suffix {
        b"end" => true,
        b"begin" => false,
        _ => return false,
    };
    let mut off = 0.;
    if suffix_end < b.len() {
        let n = XmlSpan {
            offset: s.offset + suffix_end + 1,
            length: b.len() - suffix_end - 1,
        };
        off = match time(src, n) {
            Some(n) => n,
            None => return false,
        };
        if b[suffix_end] == b'-' {
            off = -off
        }
    }
    let id = XmlSpan {
        offset: s.offset,
        length: dot,
    };
    if id.length == 0 {
        return false;
    }
    if is_begin {
        t.has_begin_sync = true;
        t.begin_sync_end = sync_end;
        t.begin_offset = off;
        t.begin_sync_id = Some(id)
    } else {
        t.has_end = true;
        t.end_is_sync = true;
        t.end_seconds = off;
        t.end_sync_id = Some(id)
    }
    true
}
pub(crate) fn path_shape(src: &[u8], s: XmlSpan) -> Option<([u8; 1024], usize, usize)> {
    let b = span(src, s)?;
    if b.is_empty() || b.len() > MAX_PATH_BYTES {
        return None;
    }
    let (mut commands, mut command_count, mut nums, mut i) = ([0; 1024], 0, 0, 0);
    while i < b.len() {
        let c = b[i];
        if c.is_ascii_alphabetic() {
            if !b"MmLlHhVvCcSsQqTtAaZz".contains(&c) || command_count >= commands.len() {
                return None;
            }
            commands[command_count] = c;
            command_count += 1;
            i += 1;
            continue;
        }
        if b" \t\r\n,".contains(&c) {
            i += 1;
            continue;
        }
        let start = i;
        if matches!(c, b'+' | b'-') {
            i += 1
        }
        let mut digits = false;
        while b.get(i).is_some_and(u8::is_ascii_digit) {
            i += 1;
            digits = true
        }
        if b.get(i) == Some(&b'.') {
            i += 1;
            while b.get(i).is_some_and(u8::is_ascii_digit) {
                i += 1;
                digits = true
            }
        }
        if !digits {
            return None;
        }
        if matches!(b.get(i), Some(b'e' | b'E')) {
            i += 1;
            if matches!(b.get(i), Some(b'+' | b'-')) {
                i += 1
            }
            let exp = i;
            while b.get(i).is_some_and(u8::is_ascii_digit) {
                i += 1
            }
            if i == exp {
                return None;
            }
        }
        if i == start {
            return None;
        }
        nums += 1;
        if nums > MAX_PATH_NUMBERS {
            return None;
        }
    }
    if command_count == 0 {
        None
    } else {
        Some((commands, command_count, nums))
    }
}
pub(crate) fn paths_match(src: &[u8], a: XmlSpan, b: XmlSpan) -> bool {
    match (path_shape(src, a), path_shape(src, b)) {
        (Some((x, xc, n)), Some((y, yc, m))) => xc == yc && n == m && x[..xc] == y[..yc],
        _ => false,
    }
}
use crate::{MotionPoint, Track};
use vexel_xml::{TokenKind, XmlSpan, XmlToken};

const MAX_POINTS: usize = 4096;
const MAX_BYTES: usize = 64 * 1024;

pub(crate) fn parse_motion(
    source: &[u8],
    span: XmlSpan,
    track: &mut Track,
    allocation_failed: &mut bool,
) -> bool {
    let Some(path) = span.slice(source) else {
        return false;
    };
    if path.is_empty() || path.len() > MAX_BYTES {
        return false;
    }
    let mut p = PathReader { b: path, pos: 0 };
    let (mut x, mut y, mut sx, mut sy) = (0.0, 0.0, 0.0, 0.0);
    let mut cmd = 0u8;
    let mut moved = false;
    while {
        p.ws();
        p.pos < path.len()
    } {
        let b = path[p.pos];
        if b.is_ascii_alphabetic() {
            cmd = b;
            p.pos += 1;
            if !b"MmLlHhVvZz".contains(&cmd) {
                return false;
            }
            if matches!(cmd, b'M' | b'm') && moved {
                return false;
            }
            if matches!(cmd, b'Z' | b'z') {
                if !moved || !push(track, &mut sx, &mut sy, allocation_failed) {
                    return false;
                }
                x = sx;
                y = sy;
                cmd = 0;
                continue;
            }
        }
        if cmd == 0 || !p.has_num() {
            return false;
        }
        let rel = cmd.is_ascii_lowercase();
        match cmd {
            b'M' | b'm' | b'L' | b'l' => {
                let Some(mut nx) = p.number() else {
                    return false;
                };
                let Some(mut ny) = p.number() else {
                    return false;
                };
                if rel {
                    nx += x;
                    ny += y
                }
                x = nx;
                y = ny;
                if !moved {
                    sx = x;
                    sy = y;
                    moved = true
                }
                if !push_xy(track, x, y, allocation_failed) {
                    return false;
                }
                if cmd == b'M' {
                    cmd = b'L'
                } else if cmd == b'm' {
                    cmd = b'l'
                }
            }
            b'H' | b'h' => {
                let Some(nx) = p.number() else { return false };
                x = if rel { x + nx } else { nx };
                if !moved || !push_xy(track, x, y, allocation_failed) {
                    return false;
                }
            }
            b'V' | b'v' => {
                let Some(ny) = p.number() else { return false };
                y = if rel { y + ny } else { ny };
                if !moved || !push_xy(track, x, y, allocation_failed) {
                    return false;
                }
            }
            _ => return false,
        }
    }
    moved && track.motion_points.len() >= 2 && track.motion_length > 0.0
}
struct PathReader<'a> {
    b: &'a [u8],
    pos: usize,
}
impl PathReader<'_> {
    fn ws(&mut self) {
        while self
            .b
            .get(self.pos)
            .is_some_and(|b| b" \t\r\n,".contains(b))
        {
            self.pos += 1
        }
    }
    fn has_num(&mut self) -> bool {
        self.ws();
        self.b
            .get(self.pos)
            .is_some_and(|b| b.is_ascii_digit() || matches!(b, b'+' | b'-' | b'.'))
    }
    fn number(&mut self) -> Option<f64> {
        self.ws();
        let start = self.pos;
        if matches!(self.b.get(self.pos), Some(b'+' | b'-')) {
            self.pos += 1
        }
        let mut digit = false;
        while self.b.get(self.pos).is_some_and(u8::is_ascii_digit) {
            digit = true;
            self.pos += 1
        }
        if self.b.get(self.pos) == Some(&b'.') {
            self.pos += 1;
            while self.b.get(self.pos).is_some_and(u8::is_ascii_digit) {
                digit = true;
                self.pos += 1
            }
        }
        if !digit {
            return None;
        }
        if matches!(self.b.get(self.pos), Some(b'e' | b'E')) {
            self.pos += 1;
            if matches!(self.b.get(self.pos), Some(b'+' | b'-')) {
                self.pos += 1
            }
            let e = self.pos;
            while self.b.get(self.pos).is_some_and(u8::is_ascii_digit) {
                self.pos += 1
            }
            if e == self.pos {
                return None;
            }
        }
        if self.pos - start >= 128 {
            return None;
        }
        let n = std::str::from_utf8(&self.b[start..self.pos])
            .ok()?
            .parse::<f64>()
            .ok()?;
        if n.is_finite() && n.abs() <= 1_000_000.0 {
            Some(n)
        } else {
            None
        }
    }
}
fn push(track: &mut Track, x: &mut f64, y: &mut f64, allocation_failed: &mut bool) -> bool {
    push_xy(track, *x, *y, allocation_failed)
}
fn push_xy(track: &mut Track, x: f64, y: f64, allocation_failed: &mut bool) -> bool {
    if !x.is_finite()
        || !y.is_finite()
        || x.abs() > 1e6
        || y.abs() > 1e6
        || track.motion_points.len() >= MAX_POINTS
    {
        return false;
    }
    let d = track
        .motion_points
        .last()
        .map_or(0.0, |p| p.distance + (x - p.x).hypot(y - p.y));
    if !d.is_finite() || d > 1e9 {
        return false;
    }
    if track.motion_points.try_reserve(1).is_err() {
        *allocation_failed = true;
        return false;
    }
    track.motion_points.push(MotionPoint { x, y, distance: d });
    track.motion_length = d;
    true
}

pub(crate) fn resolve_motion_path(
    source: &[u8],
    tokens: &[XmlToken],
    animation: usize,
) -> Option<XmlSpan> {
    if let Some(direct) = attr(source, tokens, animation, b"path") {
        return Some(direct);
    }
    let depth = tokens.get(animation)?.depth;
    let mut mp = None;
    for (i, t) in tokens.iter().enumerate().skip(animation + 1) {
        if t.kind == TokenKind::EndElement && t.depth == depth {
            break;
        }
        if t.depth == depth + 1
            && matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement)
            && t.prefix.length == 0
            && t.local_name.slice(source) == Some(b"mpath")
        {
            mp = Some(i);
            break;
        }
    }
    let m = mp?;
    let href = tokens
        .iter()
        .skip(m + 1)
        .take_while(|t| t.kind == TokenKind::Attribute)
        .find(|t| {
            t.local_name.slice(source) == Some(b"href")
                && (t.prefix.length == 0 || t.prefix.slice(source) == Some(b"xlink"))
        })?
        .value;
    let value = href.slice(source)?;
    if value.len() < 2 || value[0] != b'#' {
        return None;
    }
    let id = &value[1..];
    let mut found = None;
    for (i, t) in tokens.iter().enumerate() {
        if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement)
            || t.prefix.length != 0
            || t.local_name.slice(source) != Some(b"path")
        {
            continue;
        }
        if attr(source, tokens, i, b"id").and_then(|s| s.slice(source)) == Some(id) {
            if found.is_some() {
                return None;
            }
            found = attr(source, tokens, i, b"d")
        }
    }
    found
}
fn attr(source: &[u8], tokens: &[XmlToken], element: usize, name: &[u8]) -> Option<XmlSpan> {
    tokens.get(element)?;
    tokens
        .iter()
        .skip(element + 1)
        .take_while(|t| t.kind == TokenKind::Attribute)
        .find(|t| t.prefix.length == 0 && t.local_name.slice(source) == Some(name))
        .map(|t| t.value)
}
use crate::*;

fn duration(t: &Track) -> f64 {
    let mut d = if t.duration_indefinite {
        f64::INFINITY
    } else {
        t.duration_seconds
    };
    if t.repeat_indefinite && d.is_finite() {
        d = f64::INFINITY
    } else if d.is_finite() {
        d *= t.repeat_count
    }
    if !t.repeat_duration_indefinite && t.repeat_duration < d {
        d = t.repeat_duration
    }
    if !d.is_finite() || d > MAX_TIMELINE_SECONDS {
        MAX_TIMELINE_SECONDS
    } else {
        d
    }
}
fn resolve(
    doc: &Document<'_>,
    i: usize,
    state: &mut [u8; MAX_TRACKS],
    starts: &mut [f64; MAX_TRACKS],
) -> bool {
    if i >= doc.tracks.len() {
        return false;
    }
    if state[i] == 2 {
        return true;
    }
    if state[i] == 1 {
        starts[i] = f64::INFINITY;
        state[i] = 2;
        return true;
    }
    state[i] = 1;
    let t = &doc.tracks[i];
    if !t.supported || t.begin_indefinite {
        starts[i] = f64::INFINITY
    } else if !t.has_begin_sync {
        starts[i] = t.begin_offset
    } else {
        let Some(r) = t.begin_sync_track else {
            starts[i] = f64::INFINITY;
            state[i] = 2;
            return true;
        };
        if !resolve(doc, r, state, starts) {
            return false;
        }
        let mut s = starts[r];
        if t.begin_sync_end {
            if !s.is_finite() {
                starts[i] = f64::INFINITY;
                state[i] = 2;
                return true;
            }
            s += duration(&doc.tracks[r])
        }
        starts[i] = s + t.begin_offset
    }
    if starts[i].is_finite() && (starts[i] < 0. || starts[i] > MAX_TIMELINE_SECONDS) {
        starts[i] = f64::INFINITY
    }
    state[i] = 2;
    true
}
fn active_duration(
    doc: &Document<'_>,
    i: usize,
    state: &[u8; MAX_TRACKS],
    starts: &[f64; MAX_TRACKS],
) -> f64 {
    let t = &doc.tracks[i];
    let mut d = duration(t);
    if t.has_end {
        let mut end = t.end_seconds;
        if t.end_is_sync {
            let Some(r) = t.end_sync_track else { return 0. };
            if r >= doc.tracks.len() || state[r] != 2 || !starts[r].is_finite() {
                return 0.;
            }
            end += starts[r] + duration(&doc.tracks[r])
        }
        let e = end - starts[i];
        if e < d {
            d = e
        }
    }
    if d < 0. {
        0.
    } else {
        d.min(MAX_TIMELINE_SECONDS)
    }
}
fn distance(a: Value, b: Value) -> f64 {
    if a.kind != b.kind {
        return 0.;
    }
    match a.kind {
        ValueKind::Color => a
            .rgba
            .iter()
            .zip(b.rgba)
            .map(|(x, y)| (*x as f64 - y as f64).powi(2))
            .sum::<f64>()
            .sqrt(),
        ValueKind::Number => (b.number[0] - a.number[0]).abs(),
        ValueKind::Transform => {
            let n = (a.number[3] as usize).min(3);
            a.number[..n]
                .iter()
                .zip(&b.number[..n])
                .map(|(x, y)| (y - x).powi(2))
                .sum::<f64>()
                .sqrt()
        }
        _ => 0.,
    }
}
fn bezier(t: f64, a: f64, b: f64) -> f64 {
    let u = 1. - t;
    3. * u * u * t * a + 3. * u * t * t * b + t * t * t
}
fn spline(p: f64, c: [f64; 4]) -> f64 {
    let (mut l, mut h) = (0., 1.);
    let mut x = p;
    for _ in 0..48 {
        x = (l + h) * 0.5;
        if bezier(x, c[0], c[2]) < p {
            l = x
        } else {
            h = x
        }
    }
    bezier(x, c[1], c[3])
}
fn interpolate(t: &Track, p: f64) -> Option<Value> {
    let n = t.keys.len();
    if n == 0 {
        return None;
    }
    if n == 1 {
        return Some(t.keys[0].value);
    }
    if p <= 0. {
        return Some(t.keys[0].value);
    }
    if p >= 1. {
        return Some(t.keys[n - 1].value);
    }
    let (mut l, mut r, mut local) = (0, 1, 0.);
    if t.calc_mode == CalcMode::Paced {
        let total = (0..n - 1)
            .map(|i| distance(t.keys[i].value, t.keys[i + 1].value))
            .sum::<f64>();
        if total <= 0. {
            local = p
        } else {
            let wanted = p * total;
            let mut traversed = 0.;
            for i in 0..n - 1 {
                let d = distance(t.keys[i].value, t.keys[i + 1].value);
                if wanted <= traversed + d || i + 2 == n {
                    l = i;
                    r = i + 1;
                    local = if d > 0. { (wanted - traversed) / d } else { 0. };
                    break;
                }
                traversed += d
            }
        }
    } else {
        while r + 1 < n && p >= t.keys[r].time {
            l += 1;
            r += 1
        }
        let dt = t.keys[r].time - t.keys[l].time;
        local = if dt > 0. {
            (p - t.keys[l].time) / dt
        } else {
            0.
        }
    }
    let a = t.keys[l].value;
    let b = t.keys[r].value;
    if t.calc_mode == CalcMode::Discrete || matches!(a.kind, ValueKind::Path | ValueKind::Motion) {
        return Some(if local < 1. { a } else { b });
    }
    if t.calc_mode == CalcMode::Spline {
        local = spline(local, *t.splines.get(l)?)
    }
    if a.kind != b.kind {
        return None;
    }
    let mut v = a;
    match a.kind {
        ValueKind::Color => {
            for i in 0..4 {
                v.rgba[i] = (a.rgba[i] as f64 + (b.rgba[i] as f64 - a.rgba[i] as f64) * local)
                    .clamp(0., 255.)
                    .round() as u8
            }
            v.raw = Default::default()
        }
        ValueKind::Number => {
            v.number[0] = a.number[0] + (b.number[0] - a.number[0]) * local;
            if !v.number[0].is_finite() {
                return None;
            }
        }
        ValueKind::Transform => {
            let count = a.number[3] as usize;
            if count > 3 || count != b.number[3] as usize {
                return None;
            }
            for i in 0..count {
                v.number[i] = a.number[i] + (b.number[i] - a.number[i]) * local
            }
        }
        _ => (),
    }
    Some(v)
}
fn motion(t: &Track, p: f64) -> Option<Value> {
    if t.motion_points.len() < 2 || t.motion_length <= 0. {
        return None;
    }
    let wanted = p * t.motion_length;
    let mut r = 1;
    while r + 1 < t.motion_points.len() && wanted > t.motion_points[r].distance {
        r += 1
    }
    let a = t.motion_points[r - 1];
    let b = t.motion_points[r];
    let d = b.distance - a.distance;
    let q = if d > 0. {
        ((wanted - a.distance) / d).clamp(0., 1.)
    } else {
        0.
    };
    let mut v = Value {
        kind: ValueKind::Motion,
        ..Value::default()
    };
    v.number[0] = a.x + (b.x - a.x) * q;
    v.number[1] = a.y + (b.y - a.y) * q;
    v.number[2] = if t.motion_rotate_auto {
        (b.y - a.y).atan2(b.x - a.x).to_degrees() + if t.motion_rotate_reverse { 180. } else { 0. }
    } else {
        t.motion_fixed_rotation
    };
    v.number[3] = 1.;
    [v.number[0], v.number[1], v.number[2]]
        .iter()
        .all(|x| x.is_finite())
        .then_some(v)
}
fn accumulate(t: &Track, iteration: usize, v: &mut Value) {
    if !t.accumulate || iteration == 0 || t.keys.len() < 2 {
        return;
    }
    let a = t.keys[0].value;
    let b = t.keys[t.keys.len() - 1].value;
    match v.kind {
        ValueKind::Number if a.kind == v.kind && b.kind == v.kind => {
            v.number[0] += iteration as f64 * (b.number[0] - a.number[0])
        }
        ValueKind::Color if a.kind == v.kind && b.kind == v.kind => {
            for c in 0..4 {
                v.rgba[c] = (v.rgba[c] as f64
                    + iteration as f64 * (b.rgba[c] as f64 - a.rgba[c] as f64))
                    .clamp(0., 255.)
                    .round() as u8
            }
        }
        _ => (),
    }
}
fn one(
    doc: &Document<'_>,
    i: usize,
    state: &[u8; MAX_TRACKS],
    starts: &[f64; MAX_TRACKS],
    now: f64,
) -> Option<OverlayItem> {
    let t = &doc.tracks[i];
    let mut out = OverlayItem {
        track_index: i,
        value: Value::default(),
        iteration: 0,
        active: false,
    };
    if !t.supported || !starts[i].is_finite() || now < starts[i] {
        return Some(out);
    }
    let dur = active_duration(doc, i, state, starts);
    let elapsed = now - starts[i];
    let finished = elapsed >= dur;
    if finished && t.fill_mode != FillMode::Freeze {
        return Some(out);
    }
    let e = if finished { dur } else { elapsed };
    let (p, it) = if t.kind == Kind::Set || t.duration_indefinite || t.duration_seconds <= 0. {
        (1., 0)
    } else if finished {
        let repeats = dur / t.duration_seconds;
        let fract = repeats - repeats.floor();
        if fract > 0. && t.fill_mode == FillMode::Freeze {
            (fract, repeats.floor() as usize)
        } else {
            let iteration = if repeats > 0. {
                (repeats - 1e-12).floor() as usize
            } else {
                0
            };
            (1., iteration)
        }
    } else {
        (
            (e % t.duration_seconds) / t.duration_seconds,
            (e / t.duration_seconds).floor() as usize,
        )
    };
    let mut value = if t.kind == Kind::Motion {
        motion(t, p)?
    } else {
        let mut v = interpolate(t, p)?;
        accumulate(t, it, &mut v);
        v
    };
    if t.additive_sum && value.kind == ValueKind::Number && t.base_value.kind == ValueKind::Number {
        value.number[0] += t.base_value.number[0]
    }
    out.value = value;
    out.iteration = it;
    out.active = true;
    Some(out)
}

/// Evaluate every parsed track at a finite time in the supported timeline.
/// On invalid input or any failed evaluation, no partial overlay is returned.
pub fn evaluate(doc: &Document<'_>, time_seconds: f64) -> Option<Overlay> {
    if !time_seconds.is_finite()
        || !(0.0..=MAX_TIMELINE_SECONDS).contains(&time_seconds)
        || doc.tracks.len() > MAX_TRACKS
    {
        return None;
    }
    let mut items = Vec::new();
    items.try_reserve_exact(doc.tracks.len()).ok()?;
    let mut state = [0u8; MAX_TRACKS];
    let mut starts = [0.0; MAX_TRACKS];
    for i in 0..doc.tracks.len() {
        if !resolve(doc, i, &mut state, &mut starts) {
            return None;
        }
    }
    for i in 0..doc.tracks.len() {
        items.push(one(doc, i, &state, &starts, time_seconds)?)
    }
    Some(Overlay {
        items,
        time_seconds,
    })
}
