fn decode(src: &[u8]) -> vexel_svg_animation::Document<'_> {
    let (tokens, r) = tokenize(src, XmlLimits::default());
    assert_eq!(r.diagnostic.category, XmlError::None);
    parse(src, &tokens[..r.token_count]).unwrap()
}
