#include "animation_internal.h"

#include <errno.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

#define ANIM_MAX_PATH_VALUE (64U * 1024U)
#define ANIM_MAX_PATH_NUMBERS 4096U

typedef struct anim_element {
    size_t token;
    size_t source_offset;
    size_t source_length;
} anim_element;

bool span_eq(base_bytes source, svg_xml_span span, const char *text)
{
    size_t length = strlen(text);
    return span.offset <= source.len && span.length <= source.len - span.offset &&
           span.length == length && memcmp(source.ptr + span.offset, text, length) == 0;
}

bool token_name(base_bytes source, const svg_xml_token *token,
                       const char *name)
{
    return token->prefix.length == 0U && span_eq(source, token->local_name, name);
}

bool attr(base_bytes source, const svg_xml_token *tokens,
                 size_t token_count, size_t element, const char *name,
                 svg_xml_span *out)
{
    if (element >= token_count) return false;
    for (size_t index = element + 1U;
         index < token_count && tokens[index].kind == SVG_XML_TOKEN_ATTRIBUTE;
         ++index) {
        if (tokens[index].prefix.length == 0U &&
            span_eq(source, tokens[index].local_name, name)) {
            if (out != NULL) *out = tokens[index].value;
            return true;
        }
    }
    return false;
}

svg_xml_span attr_or_empty(base_bytes source,
                                  const svg_xml_token *tokens,
                                  size_t token_count, size_t element,
                                  const char *name)
{
    svg_xml_span value = {0U, 0U};
    (void)attr(source, tokens, token_count, element, name, &value);
    return value;
}

bool source_number(base_bytes source, svg_xml_span span, double *out)
{
    char buffer[128];
    if (span.length == 0U || span.length >= sizeof(buffer) ||
        span.offset > source.len || span.length > source.len - span.offset)
        return false;
    memcpy(buffer, source.ptr + span.offset, span.length);
    buffer[span.length] = '\0';
    errno = 0;
    char *end = NULL;
    double number = strtod(buffer, &end);
    if (errno != 0 || end != buffer + span.length || !isfinite(number)) return false;
    *out = number;
    return true;
}

bool time_value(base_bytes source, svg_xml_span span, double *out)
{
    char buffer[128];
    if (span.length == 0U || span.length >= sizeof(buffer) ||
        span.offset > source.len || span.length > source.len - span.offset)
        return false;
    memcpy(buffer, source.ptr + span.offset, span.length);
    buffer[span.length] = '\0';
    size_t length = span.length;
    double multiplier = 1.0;
    if (length >= 2U && buffer[length - 2U] == 'm' && buffer[length - 1U] == 's') {
        buffer[length - 2U] = '\0';
        multiplier = 0.001;
    } else if (length >= 1U && buffer[length - 1U] == 's') {
        buffer[length - 1U] = '\0';
    }
    errno = 0;
    char *end = NULL;
    double value = strtod(buffer, &end);
    if (errno != 0 || end == buffer || *end != '\0' || !isfinite(value) ||
        value < 0.0 || value > SVG_ANIM_MAX_TIMELINE_SECONDS / multiplier)
        return false;
    *out = value * multiplier;
    return isfinite(*out) && *out <= SVG_ANIM_MAX_TIMELINE_SECONDS;
}

static bool color_hex(uint8_t nibble, uint8_t *out)
{
    if (nibble >= '0' && nibble <= '9') *out = (uint8_t)(nibble - '0');
    else if (nibble >= 'a' && nibble <= 'f') *out = (uint8_t)(nibble - 'a' + 10U);
    else if (nibble >= 'A' && nibble <= 'F') *out = (uint8_t)(nibble - 'A' + 10U);
    else return false;
    return true;
}

static bool parse_color(base_bytes source, svg_xml_span span, uint8_t out[4])
{
    if (span.offset > source.len || span.length > source.len - span.offset) return false;
    const uint8_t *text = source.ptr + span.offset;
    size_t length = span.length;
    if (length == 4U && memcmp(text, "none", 4U) == 0) {
        memset(out, 0, 4U);
        return true;
    }
    if (length == 4U && text[0] == '#') {
        for (size_t channel = 0U; channel < 3U; ++channel) {
            uint8_t nibble = 0U;
            if (!color_hex(text[channel + 1U], &nibble)) return false;
            out[channel] = (uint8_t)(nibble * 17U);
        }
        out[3] = 255U;
        return true;
    }
    if ((length == 7U || length == 9U) && text[0] == '#') {
        size_t channels = length == 9U ? 4U : 3U;
        for (size_t channel = 0U; channel < channels; ++channel) {
            uint8_t high = 0U, low = 0U;
            if (!color_hex(text[1U + channel * 2U], &high) ||
                !color_hex(text[2U + channel * 2U], &low)) return false;
            out[channel] = (uint8_t)(high * 16U + low);
        }
        if (channels == 3U) out[3] = 255U;
        return true;
    }
    struct named_color { const char *name; uint8_t rgba[4]; };
    static const struct named_color named[] = {
        {"black", {0U, 0U, 0U, 255U}}, {"white", {255U, 255U, 255U, 255U}},
        {"red", {255U, 0U, 0U, 255U}}, {"green", {0U, 128U, 0U, 255U}},
        {"blue", {0U, 0U, 255U, 255U}}, {"yellow", {255U, 255U, 0U, 255U}},
        {"cyan", {0U, 255U, 255U, 255U}}, {"magenta", {255U, 0U, 255U, 255U}},
        {"gray", {128U, 128U, 128U, 255U}}, {"grey", {128U, 128U, 128U, 255U}},
        {"transparent", {0U, 0U, 0U, 0U}}
    };
    for (size_t index = 0U; index < sizeof(named) / sizeof(named[0]); ++index) {
        size_t name_length = strlen(named[index].name);
        if (length == name_length && memcmp(text, named[index].name, length) == 0) {
            memcpy(out, named[index].rgba, 4U);
            return true;
        }
    }
    return false;
}

static bool parse_transform_value(base_bytes source, svg_xml_span span,
                                  const char *type, svg_anim_value *out)
{
    if (span.offset > source.len || span.length > source.len - span.offset ||
        span.length == 0U || span.length > 256U) return false;
    char buffer[257];
    memcpy(buffer, source.ptr + span.offset, span.length);
    buffer[span.length] = '\0';
    double values[4] = {0.0, 0.0, 0.0, 0.0};
    size_t count = 0U;
    char *cursor = buffer;
    while (*cursor != '\0') {
        while (*cursor == ' ' || *cursor == '\t' || *cursor == '\r' ||
               *cursor == '\n' || *cursor == ',') cursor++;
        if (*cursor == '\0') break;
        if (count >= 4U) return false;
        errno = 0;
        char *end = NULL;
        double number = strtod(cursor, &end);
        if (errno != 0 || end == cursor || !isfinite(number)) return false;
        values[count++] = number;
        cursor = end;
    }
    size_t minimum = strcmp(type, "rotate") == 0 ? 1U : 1U;
    size_t maximum = strcmp(type, "rotate") == 0 ? 3U :
                     (strcmp(type, "translate") == 0 ||
                      strcmp(type, "scale") == 0 ? 2U : 1U);
    if (count < minimum || count > maximum) return false;
    out->kind = SVG_ANIM_VALUE_TRANSFORM;
    memcpy(out->number, values, sizeof(values));
    out->number[3] = (double)count;
    out->raw_offset = span.offset;
    out->raw_length = span.length;
    return true;
}

static bool parse_path_shape(base_bytes source, svg_xml_span span,
                             uint8_t *commands, size_t command_capacity,
                             size_t *command_count, size_t *number_count)
{
    if (span.offset > source.len || span.length > source.len - span.offset ||
        span.length == 0U || span.length > ANIM_MAX_PATH_VALUE) return false;
    size_t c_count = 0U, n_count = 0U;
    size_t cursor = span.offset, limit = span.offset + span.length;
    while (cursor < limit) {
        uint8_t byte = source.ptr[cursor];
        if ((byte >= 'A' && byte <= 'Z') || (byte >= 'a' && byte <= 'z')) {
            if (byte != 'M' && byte != 'm' && byte != 'L' && byte != 'l' &&
                byte != 'H' && byte != 'h' && byte != 'V' && byte != 'v' &&
                byte != 'C' && byte != 'c' && byte != 'S' && byte != 's' &&
                byte != 'Q' && byte != 'q' && byte != 'T' && byte != 't' &&
                byte != 'A' && byte != 'a' && byte != 'Z' && byte != 'z') return false;
            if (c_count >= command_capacity) return false;
            commands[c_count++] = byte;
            cursor++;
            continue;
        }
        if (byte == ' ' || byte == '\t' || byte == '\r' || byte == '\n' || byte == ',') {
            cursor++;
            continue;
        }
        size_t start = cursor;
        if (byte == '+' || byte == '-') cursor++;
        bool digits = false;
        while (cursor < limit && source.ptr[cursor] >= '0' && source.ptr[cursor] <= '9') {
            digits = true;
            cursor++;
        }
        if (cursor < limit && source.ptr[cursor] == '.') {
            cursor++;
            while (cursor < limit && source.ptr[cursor] >= '0' && source.ptr[cursor] <= '9') {
                digits = true;
                cursor++;
            }
        }
        if (!digits) return false;
        if (cursor < limit && (source.ptr[cursor] == 'e' || source.ptr[cursor] == 'E')) {
            cursor++;
            if (cursor < limit && (source.ptr[cursor] == '+' || source.ptr[cursor] == '-')) cursor++;
            size_t exponent = cursor;
            while (cursor < limit && source.ptr[cursor] >= '0' && source.ptr[cursor] <= '9') cursor++;
            if (cursor == exponent) return false;
        }
        if (cursor <= start || ++n_count > ANIM_MAX_PATH_NUMBERS) return false;
    }
    *command_count = c_count;
    *number_count = n_count;
    return c_count != 0U;
}

bool path_structures_match(base_bytes source, svg_xml_span left,
                                  svg_xml_span right)
{
    uint8_t left_commands[1024], right_commands[1024];
    size_t lc = 0U, rc = 0U, ln = 0U, rn = 0U;
    return parse_path_shape(source, left, left_commands, sizeof(left_commands), &lc, &ln) &&
           parse_path_shape(source, right, right_commands, sizeof(right_commands), &rc, &rn) &&
           lc == rc && ln == rn && memcmp(left_commands, right_commands, lc) == 0;
}

svg_anim_attribute attribute_kind(base_bytes source, svg_xml_span name,
                                         bool *is_transform, bool *is_motion)
{
    static const struct { const char *name; svg_anim_attribute value; } attrs[] = {
        {"x", SVG_ANIM_ATTR_X}, {"y", SVG_ANIM_ATTR_Y},
        {"width", SVG_ANIM_ATTR_WIDTH}, {"height", SVG_ANIM_ATTR_HEIGHT},
        {"cx", SVG_ANIM_ATTR_CX}, {"cy", SVG_ANIM_ATTR_CY},
        {"r", SVG_ANIM_ATTR_R}, {"rx", SVG_ANIM_ATTR_RX},
        {"ry", SVG_ANIM_ATTR_RY}, {"opacity", SVG_ANIM_ATTR_OPACITY},
        {"fill-opacity", SVG_ANIM_ATTR_FILL_OPACITY},
        {"stroke-opacity", SVG_ANIM_ATTR_STROKE_OPACITY},
        {"fill", SVG_ANIM_ATTR_FILL}, {"stroke", SVG_ANIM_ATTR_STROKE},
        {"stroke-width", SVG_ANIM_ATTR_STROKE_WIDTH},
        {"stroke-dashoffset", SVG_ANIM_ATTR_STROKE_DASHOFFSET},
        {"d", SVG_ANIM_ATTR_D}
    };
    *is_transform = span_eq(source, name, "transform");
    *is_motion = false;
    for (size_t index = 0U; index < sizeof(attrs) / sizeof(attrs[0]); ++index)
        if (span_eq(source, name, attrs[index].name)) return attrs[index].value;
    return SVG_ANIM_ATTR_MOTION;
}

const char *svg_anim_attribute_name(svg_anim_attribute attribute)
{
    static const char *names[] = {
        "x", "y", "width", "height", "cx", "cy", "r", "rx", "ry",
        "opacity", "fill-opacity", "stroke-opacity", "fill", "stroke",
        "stroke-width", "stroke-dashoffset", "d", "transform", "motion"
    };
    return (size_t)attribute < sizeof(names) / sizeof(names[0]) ?
           names[attribute] : "unknown";
}

const char *svg_anim_diagnostic_name(svg_anim_diagnostic_kind kind)
{
    static const char *names[] = {
        "unsupported-element", "unsupported-attribute", "unsupported-timing",
        "unsupported-composition", "unsupported-path", "css-animation",
        "invalid-track"
    };
    return (size_t)kind < sizeof(names) / sizeof(names[0]) ? names[kind] : "unknown";
}

void add_diagnostic(svg_anim_document *document,
                           svg_anim_diagnostic_kind kind, size_t offset)
{
    if (document->diagnostic_count >= SVG_ANIM_MAX_DIAGNOSTICS) return;
    document->diagnostics[document->diagnostic_count++] =
        (svg_anim_diagnostic){kind, offset};
}

bool element_span(const svg_xml_token *tokens, size_t token_count,
                         size_t element, size_t *offset, size_t *length)
{
    if (element >= token_count) return false;
    size_t start = tokens[element].source.offset;
    size_t end = tokens[element].source.offset + tokens[element].source.length;
    if (tokens[element].kind == SVG_XML_TOKEN_START_ELEMENT) {
        size_t depth = tokens[element].depth;
        bool found = false;
        for (size_t index = element + 1U; index < token_count; ++index) {
            if (tokens[index].kind == SVG_XML_TOKEN_END_ELEMENT &&
                tokens[index].depth == depth) {
                end = tokens[index].source.offset + tokens[index].source.length;
                found = true;
                break;
            }
        }
        if (!found) return false;
    }
    if (end < start) return false;
    *offset = start;
    *length = end - start;
    return true;
}

bool parse_sync_time(base_bytes source, svg_xml_span span,
                            svg_anim_track *track, bool is_begin)
{
    if (span_eq(source, span, "indefinite")) {
        if (is_begin) track->begin_indefinite = true;
        else track->has_end = false;
        return true;
    }
    if (time_value(source, span, is_begin ? &track->begin_offset : &track->end_seconds)) {
        if (!is_begin) track->has_end = true;
        return true;
    }
    size_t limit = span.offset + span.length;
    size_t dot = span.offset;
    while (dot < limit && source.ptr[dot] != '.') dot++;
    if (dot == span.offset || dot == limit) return false;
    size_t suffix_end = dot + 1U;
    while (suffix_end < limit && source.ptr[suffix_end] != '+' &&
           source.ptr[suffix_end] != '-') suffix_end++;
    svg_xml_span suffix = {dot + 1U, suffix_end - dot - 1U};
    bool sync_end = span_eq(source, suffix, "end");
    if (!sync_end && !span_eq(source, suffix, "begin")) return false;
    svg_xml_span id = {span.offset, dot - span.offset};
    double offset = 0.0;
    if (suffix_end < limit) {
        bool negative = source.ptr[suffix_end] == '-';
        svg_xml_span offset_span = {suffix_end + 1U, limit - suffix_end - 1U};
        if (!time_value(source, offset_span, &offset)) return false;
        if (negative) offset = -offset;
    }
    if (id.length == 0U) return false;
    if (is_begin) {
        track->has_begin_sync = true;
        track->begin_sync_end = sync_end;
        track->begin_offset = offset;
        track->begin_sync_track = SIZE_MAX;
    } else {
        track->has_end = true;
        track->end_is_sync = true;
        track->end_sync_track = SIZE_MAX;
        track->end_seconds = offset;
    }
    if (is_begin) track->begin_sync_id = id;
    else track->end_sync_id = id;
    return true;
}

bool parse_value(base_bytes source, svg_xml_span span,
                        svg_anim_attribute attribute, svg_anim_kind kind,
                        const char *transform_type, svg_anim_value *out)
{
    *out = (svg_anim_value){0};
    if (kind == SVG_ANIM_KIND_TRANSFORM) {
        return parse_transform_value(source, span, transform_type, out);
    }
    if (kind == SVG_ANIM_KIND_MOTION) {
        out->kind = SVG_ANIM_VALUE_MOTION;
        out->raw_offset = span.offset;
        out->raw_length = span.length;
        return true;
    }
    if (attribute == SVG_ANIM_ATTR_D) {
        out->kind = SVG_ANIM_VALUE_PATH;
        out->raw_offset = span.offset;
        out->raw_length = span.length;
        return true;
    }
    if (attribute == SVG_ANIM_ATTR_FILL || attribute == SVG_ANIM_ATTR_STROKE) {
        out->kind = SVG_ANIM_VALUE_COLOR;
        out->raw_offset = span.offset;
        out->raw_length = span.length;
        return parse_color(source, span, out->rgba);
    }
    out->kind = SVG_ANIM_VALUE_NUMBER;
    return source_number(source, span, &out->number[0]);
}

bool split_value_spans(base_bytes source, svg_xml_span values,
                              svg_xml_span *out, size_t capacity,
                              size_t *out_count)
{
    if (values.offset > source.len || values.length > source.len - values.offset) return false;
    size_t count = 0U, cursor = values.offset, end = values.offset + values.length;
    while (cursor <= end) {
        size_t item_start = cursor;
        while (cursor < end && source.ptr[cursor] != ';') cursor++;
        size_t item_end = cursor;
        while (item_start < item_end && (source.ptr[item_start] == ' ' ||
               source.ptr[item_start] == '\t' || source.ptr[item_start] == '\r' ||
               source.ptr[item_start] == '\n')) item_start++;
        while (item_end > item_start && (source.ptr[item_end - 1U] == ' ' ||
               source.ptr[item_end - 1U] == '\t' || source.ptr[item_end - 1U] == '\r' ||
               source.ptr[item_end - 1U] == '\n')) item_end--;
        if (item_start == item_end || count >= capacity) return false;
        out[count++] = (svg_xml_span){item_start, item_end - item_start};
        if (cursor == end) break;
        cursor++;
    }
    *out_count = count;
    return count != 0U;
}

static bool is_color_attribute(svg_anim_attribute attribute)
{
    return attribute == SVG_ANIM_ATTR_FILL || attribute == SVG_ANIM_ATTR_STROKE;
}

bool base_attribute_value(base_bytes source, const svg_xml_token *tokens,
                                 size_t token_count, size_t target,
                                 svg_anim_attribute attribute, svg_anim_kind kind,
                                 const char *transform_type, svg_anim_value *out)
{
    if (kind == SVG_ANIM_KIND_TRANSFORM) {
        *out = (svg_anim_value){.kind = SVG_ANIM_VALUE_TRANSFORM};
        if (strcmp(transform_type, "scale") == 0) {
            out->number[0] = 1.0;
            out->number[1] = 1.0;
            out->number[3] = 2.0;
        } else if (strcmp(transform_type, "translate") == 0) {
            out->number[3] = 2.0;
        } else {
            out->number[3] = 1.0;
        }
        return true;
    }
    if (kind == SVG_ANIM_KIND_MOTION) {
        *out = (svg_anim_value){.kind = SVG_ANIM_VALUE_MOTION};
        return true;
    }
    svg_xml_span raw;
    if (!attr(source, tokens, token_count, target,
              svg_anim_attribute_name(attribute), &raw)) {
        if (is_color_attribute(attribute)) {
            *out = (svg_anim_value){.kind = SVG_ANIM_VALUE_COLOR,
                .rgba = {0U, 0U, 0U, 0U}};
            if (attribute == SVG_ANIM_ATTR_FILL) out->rgba[3] = 255U;
            return true;
        }
        *out = (svg_anim_value){.kind = SVG_ANIM_VALUE_NUMBER};
        if (attribute == SVG_ANIM_ATTR_OPACITY ||
            attribute == SVG_ANIM_ATTR_FILL_OPACITY ||
            attribute == SVG_ANIM_ATTR_STROKE_OPACITY)
            out->number[0] = 1.0;
        return true;
    }
    return parse_value(source, raw, attribute, kind, transform_type, out);
}

bool parse_key_times(base_bytes source, svg_xml_span span,
                            svg_anim_track *track)
{
    if (span.length == 0U) return true;
    svg_xml_span pieces[SVG_ANIM_MAX_VALUES];
    size_t count = 0U;
    if (!split_value_spans(source, span, pieces, SVG_ANIM_MAX_VALUES, &count) ||
        count != track->key_count) return false;
    double previous = -1.0;
    for (size_t index = 0U; index < count; ++index) {
        double value = 0.0;
        if (!source_number(source, pieces[index], &value) || value < 0.0 ||
            value > 1.0 || (index != 0U && value <= previous)) return false;
        track->keys[index].time = value;
        previous = value;
    }
    return track->keys[0].time == 0.0 &&
           (track->kind == SVG_ANIM_KIND_SET ||
            track->keys[count - 1U].time == 1.0);
}

bool parse_splines(base_bytes source, svg_xml_span span,
                          svg_anim_track *track)
{
    if (track->calc_mode != SVG_ANIM_CALC_SPLINE) return span.length == 0U;
    size_t expected = track->key_count > 0U ? track->key_count - 1U : 0U;
    if (expected == 0U || expected > SVG_ANIM_MAX_VALUES) return false;
    track->splines = calloc(expected, sizeof(*track->splines));
    if (track->splines == NULL) return false;
    track->spline_count = expected;
    svg_xml_span pieces[SVG_ANIM_MAX_VALUES];
    size_t count = 0U;
    if (!split_value_spans(source, span, pieces, SVG_ANIM_MAX_VALUES, &count) ||
        count != expected) return false;
    for (size_t index = 0U; index < count; ++index) {
        char buffer[256];
        if (pieces[index].length >= sizeof(buffer)) return false;
        memcpy(buffer, source.ptr + pieces[index].offset, pieces[index].length);
        buffer[pieces[index].length] = '\0';
        char *cursor = buffer;
        for (size_t coordinate = 0U; coordinate < 4U; ++coordinate) {
            while (*cursor == ' ' || *cursor == '\t' || *cursor == '\r' ||
                   *cursor == '\n' || *cursor == ',') cursor++;
            errno = 0;
            char *end = NULL;
            double value = strtod(cursor, &end);
            if (errno != 0 || end == cursor || !isfinite(value) || value < 0.0 ||
                value > 1.0) return false;
            track->splines[index][coordinate] = value;
            cursor = end;
        }
        while (*cursor == ' ' || *cursor == '\t' || *cursor == '\r' ||
               *cursor == '\n' || *cursor == ',') cursor++;
        if (*cursor != '\0') return false;
    }
    return true;
}

bool parse_repeat(base_bytes source, svg_xml_span span,
                         svg_anim_track *track)
{
    if (span.length == 0U) {
        track->repeat_count = 1.0;
        return true;
    }
    if (span_eq(source, span, "indefinite")) {
        track->repeat_indefinite = true;
        track->repeat_count = INFINITY;
        return true;
    }
    return source_number(source, span, &track->repeat_count) &&
           track->repeat_count > 0.0 && track->repeat_count <= 100000.0;
}

bool parse_calc_fill(base_bytes source, const svg_xml_token *tokens,
                            size_t token_count, size_t element,
                            svg_anim_track *track, size_t *diagnostic_offset,
                            svg_anim_document *document)
{
    svg_xml_span span = attr_or_empty(source, tokens, token_count, element, "calcMode");
    if (span.length == 0U || span_eq(source, span, "linear"))
        track->calc_mode = SVG_ANIM_CALC_LINEAR;
    else if (span_eq(source, span, "discrete"))
        track->calc_mode = SVG_ANIM_CALC_DISCRETE;
    else if (span_eq(source, span, "spline"))
        track->calc_mode = SVG_ANIM_CALC_SPLINE;
    else if (span_eq(source, span, "paced"))
        track->calc_mode = SVG_ANIM_CALC_PACED;
    else {
        *diagnostic_offset = span.offset;
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ATTRIBUTE, span.offset);
        return false;
    }
    span = attr_or_empty(source, tokens, token_count, element, "fill");
    if (span.length == 0U || span_eq(source, span, "remove"))
        track->fill_mode = SVG_ANIM_FILL_REMOVE;
    else if (span_eq(source, span, "freeze"))
        track->fill_mode = SVG_ANIM_FILL_FREEZE;
    else {
        *diagnostic_offset = span.offset;
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ATTRIBUTE, span.offset);
        return false;
    }
    return true;
}

#include "animation_internal.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

static bool parse_track(base_bytes source, const svg_xml_token *tokens,
                        size_t token_count, size_t element, size_t parent,
                        svg_anim_document *document, svg_anim_track *out)
{
    memset(out, 0, sizeof(*out));
    out->begin_sync_track = SIZE_MAX;
    out->end_sync_track = SIZE_MAX;
    out->repeat_duration = INFINITY;
    out->begin_indefinite = false;
    out->supported = true;
    const svg_xml_token *tag = &tokens[element];
    if (tag->prefix.length != 0U) {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ELEMENT, tag->name.offset);
        return false;
    }
    if (token_name(source, tag, "animate")) out->kind = SVG_ANIM_KIND_ANIMATE;
    else if (token_name(source, tag, "animateTransform")) out->kind = SVG_ANIM_KIND_TRANSFORM;
    else if (token_name(source, tag, "set")) out->kind = SVG_ANIM_KIND_SET;
    else if (token_name(source, tag, "animateMotion")) out->kind = SVG_ANIM_KIND_MOTION;
    else {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ELEMENT, tag->name.offset);
        return false;
    }
    if (parent >= token_count) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
        return false;
    }
    if (!element_span(tokens, token_count, parent, &out->target_offset,
                      &out->target_length) ||
        !element_span(tokens, token_count, element, &out->element_offset,
                      &out->element_length)) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
        return false;
    }
    svg_xml_span id = attr_or_empty(source, tokens, token_count, element, "id");
    out->id = id;
    if (out->kind == SVG_ANIM_KIND_MOTION) {
        out->attribute = SVG_ANIM_ATTR_MOTION;
    } else {
        svg_xml_span attribute_name = attr_or_empty(source, tokens, token_count,
                                                     element, "attributeName");
        if (attribute_name.length == 0U) {
            add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
            return false;
        }
        bool transform = false, motion = false;
        out->attribute = attribute_kind(source, attribute_name, &transform, &motion);
        if (out->kind == SVG_ANIM_KIND_TRANSFORM) {
            if (!transform) {
                add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ATTRIBUTE,
                               attribute_name.offset);
                return false;
            }
        } else if (transform || out->attribute == SVG_ANIM_ATTR_MOTION) {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ATTRIBUTE,
                           attribute_name.offset);
            return false;
        }
    }
    svg_xml_span transform_type_span = attr_or_empty(source, tokens, token_count,
                                                       element, "type");
    svg_xml_span attribute_type = attr_or_empty(source, tokens, token_count,
                                                 element, "attributeType");
    if (attribute_type.length != 0U && !span_eq(source, attribute_type, "XML")) {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ATTRIBUTE,
                       attribute_type.offset);
        return false;
    }
    char transform_type[16] = "translate";
    if (out->kind == SVG_ANIM_KIND_TRANSFORM) {
        if (transform_type_span.length == 0U || transform_type_span.length >= sizeof(transform_type)) {
            add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
            return false;
        }
        memcpy(transform_type, source.ptr + transform_type_span.offset,
               transform_type_span.length);
        transform_type[transform_type_span.length] = '\0';
        if (strcmp(transform_type, "translate") != 0 && strcmp(transform_type, "scale") != 0 &&
            strcmp(transform_type, "rotate") != 0 && strcmp(transform_type, "skewX") != 0 &&
            strcmp(transform_type, "skewY") != 0) {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ATTRIBUTE,
                           transform_type_span.offset);
            return false;
        }
        if (strcmp(transform_type, "translate") == 0)
            out->transform_type = SVG_ANIM_TRANSFORM_TRANSLATE;
        else if (strcmp(transform_type, "scale") == 0)
            out->transform_type = SVG_ANIM_TRANSFORM_SCALE;
        else if (strcmp(transform_type, "rotate") == 0)
            out->transform_type = SVG_ANIM_TRANSFORM_ROTATE;
        else if (strcmp(transform_type, "skewX") == 0)
            out->transform_type = SVG_ANIM_TRANSFORM_SKEW_X;
        else out->transform_type = SVG_ANIM_TRANSFORM_SKEW_Y;
    }
    size_t ignored_offset = 0U;
    if (!parse_calc_fill(source, tokens, token_count, element, out,
                         &ignored_offset, document)) return false;
    svg_xml_span additive = attr_or_empty(source, tokens, token_count, element, "additive");
    if (additive.length != 0U && !span_eq(source, additive, "replace")) {
        if (span_eq(source, additive, "sum")) out->additive_sum = true;
        else {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_COMPOSITION,
                           additive.offset);
            return false;
        }
    }
    svg_xml_span accumulate = attr_or_empty(source, tokens, token_count, element,
                                             "accumulate");
    if (accumulate.length != 0U && !span_eq(source, accumulate, "none")) {
        if (span_eq(source, accumulate, "sum")) out->accumulate = true;
        else {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_COMPOSITION,
                           accumulate.offset);
            return false;
        }
    }
    if (out->kind == SVG_ANIM_KIND_MOTION &&
        (out->additive_sum || out->accumulate)) {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_COMPOSITION,
                       tag->name.offset);
        return false;
    }
    if ((out->kind == SVG_ANIM_KIND_TRANSFORM && out->accumulate) ||
        (out->attribute == SVG_ANIM_ATTR_D &&
         (out->additive_sum || out->accumulate))) {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_COMPOSITION,
                       tag->name.offset);
        return false;
    }
    svg_xml_span begin = attr_or_empty(source, tokens, token_count, element, "begin");
    if (begin.length != 0U && !parse_sync_time(source, begin, out, true)) {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_TIMING, begin.offset);
        return false;
    }
    svg_xml_span end = attr_or_empty(source, tokens, token_count, element, "end");
    if (end.length != 0U) {
        if (!parse_sync_time(source, end, out, false)) {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_TIMING, end.offset);
            return false;
        }
        if (out->end_is_sync && out->key_count == 0U) { /* sync ID saved after keys exist */ }
    }
    svg_xml_span duration = attr_or_empty(source, tokens, token_count, element, "dur");
    if (duration.length == 0U && out->kind != SVG_ANIM_KIND_SET) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
        return false;
    }
    if (span_eq(source, duration, "indefinite")) out->duration_indefinite = true;
    else if (duration.length != 0U &&
             !time_value(source, duration, &out->duration_seconds)) {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_TIMING, duration.offset);
        return false;
    }
    if (!out->duration_indefinite && out->kind != SVG_ANIM_KIND_SET &&
        !(out->duration_seconds > 0.0)) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, duration.offset);
        return false;
    }
    if (out->kind == SVG_ANIM_KIND_SET && duration.length == 0U)
        out->duration_indefinite = true;
    if (!parse_repeat(source, attr_or_empty(source, tokens, token_count,
                                           element, "repeatCount"), out)) {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_TIMING, tag->name.offset);
        return false;
    }
    svg_xml_span repeat_dur = attr_or_empty(source, tokens, token_count, element,
                                             "repeatDur");
    if (span_eq(source, repeat_dur, "indefinite")) out->repeat_duration_indefinite = true;
    else if (repeat_dur.length != 0U) {
        if (!time_value(source, repeat_dur, &out->repeat_duration)) {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_TIMING,
                           repeat_dur.offset);
            return false;
        }
    }
    if (out->kind == SVG_ANIM_KIND_SET) out->repeat_count = 1.0;
    out->base_value = (svg_anim_value){0};
    if (out->kind != SVG_ANIM_KIND_MOTION &&
        !base_attribute_value(source, tokens, token_count, parent,
            out->attribute, out->kind, transform_type, &out->base_value)) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
        return false;
    }
    svg_xml_span values = attr_or_empty(source, tokens, token_count, element, "values");
    svg_xml_span from = attr_or_empty(source, tokens, token_count, element, "from");
    svg_xml_span to = attr_or_empty(source, tokens, token_count, element, "to");
    svg_xml_span by = attr_or_empty(source, tokens, token_count, element, "by");
    if (values.length != 0U && (from.length != 0U || to.length != 0U || by.length != 0U)) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, values.offset);
        return false;
    }
    svg_xml_span pieces[SVG_ANIM_MAX_VALUES];
    size_t count = 0U;
    bool implicit_from = false;
    bool by_value = false;
    if (out->kind == SVG_ANIM_KIND_MOTION) {
        svg_xml_span path = {0U, 0U};
        if (!svg_anim_resolve_motion_path(source, tokens, token_count,
                                          element, &path) ||
            !svg_anim_parse_motion_path(source, path, out)) {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_PATH, tag->name.offset);
            return false;
        }
        svg_xml_span rotate = attr_or_empty(source, tokens, token_count,
                                            element, "rotate");
        if (span_eq(source, rotate, "auto")) out->motion_rotate_auto = true;
        else if (span_eq(source, rotate, "auto-reverse")) {
            out->motion_rotate_auto = true;
            out->motion_rotate_reverse = true;
        } else if (rotate.length != 0U &&
                   !source_number(source, rotate, &out->motion_fixed_rotation)) {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ATTRIBUTE,
                           rotate.offset);
            return false;
        }
        pieces[count++] = path;
    } else if (values.length != 0U) {
        if (!split_value_spans(source, values, pieces, SVG_ANIM_MAX_VALUES, &count)) {
            add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, values.offset);
            return false;
        }
    } else if (out->kind == SVG_ANIM_KIND_SET) {
        if (to.length == 0U) {
            add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
            return false;
        }
        pieces[count++] = to;
    } else if (from.length != 0U && to.length != 0U) {
        pieces[count++] = from;
        pieces[count++] = to;
    } else if (to.length != 0U) {
        if (out->kind != SVG_ANIM_KIND_SET) {
            implicit_from = true;
            pieces[count++] = to;
        } else pieces[count++] = to;
    } else if (by.length != 0U) {
        implicit_from = true;
        by_value = true;
        pieces[count++] = by;
    } else {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
        return false;
    }
    if (count == 0U || count > SVG_ANIM_MAX_VALUES) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
        return false;
    }
    size_t source_value_count = count;
    if (implicit_from) {
        if (count >= SVG_ANIM_MAX_VALUES) {
            add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK, tag->name.offset);
            return false;
        }
        count++;
    }
    out->keys = calloc(count, sizeof(*out->keys));
    if (out->keys == NULL) return false;
    out->key_count = count;
    if (implicit_from) {
        out->keys[0].value = out->base_value;
        out->keys[0].source_offset = out->base_value.raw_offset;
        out->keys[0].source_length = out->base_value.raw_length;
        out->keys[0].time = 0.0;
    }
    for (size_t index = 0U; index < source_value_count; ++index) {
        svg_anim_value value;
        if (!parse_value(source, pieces[index], out->attribute, out->kind,
                         transform_type, &value)) {
            add_diagnostic(document, out->attribute == SVG_ANIM_ATTR_D ?
                SVG_ANIM_DIAG_UNSUPPORTED_PATH : SVG_ANIM_DIAG_INVALID_TRACK,
                pieces[index].offset);
            return false;
        }
        size_t key_index = index + (implicit_from ? 1U : 0U);
        if (by_value) {
            if (value.kind != SVG_ANIM_VALUE_NUMBER ||
                out->base_value.kind != SVG_ANIM_VALUE_NUMBER) {
                add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_COMPOSITION,
                               pieces[index].offset);
                return false;
            }
            value.number[0] += out->base_value.number[0];
        }
        out->keys[key_index].value = value;
        out->keys[key_index].source_offset = pieces[index].offset;
        out->keys[key_index].source_length = pieces[index].length;
        out->keys[key_index].time = count == 1U ? 0.0 :
            (double)key_index / (double)(count - 1U);
    }
    if (out->kind == SVG_ANIM_KIND_ANIMATE && out->attribute == SVG_ANIM_ATTR_D) {
        svg_xml_span base_path = attr_or_empty(source, tokens, token_count, parent, "d");
        if (base_path.length == 0U) {
            add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_PATH, tag->name.offset);
            return false;
        }
        for (size_t index = 0U; index < count; ++index) {
            svg_xml_span current = {out->keys[index].value.raw_offset,
                                    out->keys[index].value.raw_length};
            if (!path_structures_match(source, base_path, current)) {
                add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_PATH,
                               current.offset);
                return false;
            }
        }
    }
    svg_xml_span key_times = attr_or_empty(source, tokens, token_count, element,
                                            "keyTimes");
    if (!parse_key_times(source, key_times, out)) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK,
                       key_times.length == 0U ? tag->name.offset : key_times.offset);
        return false;
    }
    if (out->calc_mode == SVG_ANIM_CALC_PACED && key_times.length != 0U) {
        add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_ATTRIBUTE,
                       key_times.offset);
        return false;
    }
    svg_xml_span splines = attr_or_empty(source, tokens, token_count, element,
                                          "keySplines");
    if (!parse_splines(source, splines, out)) {
        add_diagnostic(document, SVG_ANIM_DIAG_INVALID_TRACK,
                       splines.length == 0U ? tag->name.offset : splines.offset);
        return false;
    }
    return true;
}

static bool span_id_eq(base_bytes source, svg_xml_span left, svg_xml_span right)
{
    return left.length != 0U && left.length == right.length &&
           left.offset <= source.len && right.offset <= source.len &&
           left.length <= source.len - left.offset &&
           right.length <= source.len - right.offset &&
           memcmp(source.ptr + left.offset, source.ptr + right.offset, left.length) == 0;
}

static bool resolve_syncbases(svg_anim_document *document)
{
    for (size_t index = 0U; index < document->track_count; ++index) {
        svg_anim_track *track = &document->tracks[index];
        if (track->has_begin_sync) {
            svg_xml_span sync_id = track->begin_sync_id;
            size_t found = SIZE_MAX, matches = 0U;
            for (size_t candidate = 0U; candidate < document->track_count; ++candidate) {
                if (span_id_eq(document->source, sync_id,
                               document->tracks[candidate].id)) {
                    found = candidate;
                    matches++;
                }
            }
            if (matches != 1U) {
                add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_TIMING,
                               sync_id.offset);
                track->supported = false;
            } else track->begin_sync_track = found;
        }
        if (track->end_is_sync) {
            svg_xml_span sync_id = track->end_sync_id;
            size_t found = SIZE_MAX, matches = 0U;
            for (size_t candidate = 0U; candidate < document->track_count; ++candidate) {
                if (span_id_eq(document->source, sync_id,
                               document->tracks[candidate].id)) {
                    found = candidate;
                    matches++;
                }
            }
            if (matches != 1U) {
                add_diagnostic(document, SVG_ANIM_DIAG_UNSUPPORTED_TIMING,
                               sync_id.offset);
                track->supported = false;
            } else track->end_sync_track = found;
        }
    }
    return true;
}

static bool contains_bytes(base_bytes source, svg_xml_span span, const char *needle)
{
    size_t length = strlen(needle);
    if (span.offset > source.len || span.length > source.len - span.offset ||
        span.length < length) return false;
    for (size_t index = 0U; index + length <= span.length; ++index)
        if (memcmp(source.ptr + span.offset + index, needle, length) == 0) return true;
    return false;
}

bool svg_anim_parse(base_bytes source, const svg_xml_token *tokens,
                    size_t token_count, svg_anim_document *out,
                    size_t *error_offset)
{
    if (error_offset != NULL) *error_offset = 0U;
    if (out == NULL || tokens == NULL || !base_bytes_valid(source)) return false;
    *out = (svg_anim_document){.source = source};
    out->tracks = calloc(SVG_ANIM_MAX_TRACKS, sizeof(*out->tracks));
    if (out->tracks == NULL) return false;
    for (size_t index = 0U; index < token_count; ++index) {
        const svg_xml_token *token = &tokens[index];
        if (token->kind == SVG_XML_TOKEN_START_ELEMENT ||
            token->kind == SVG_XML_TOKEN_EMPTY_ELEMENT) {
            if (token_name(source, token, "style")) {
                size_t end = index + 1U;
                while (end < token_count &&
                       !(tokens[end].kind == SVG_XML_TOKEN_END_ELEMENT &&
                         tokens[end].depth == token->depth)) {
                    if (tokens[end].kind == SVG_XML_TOKEN_TEXT &&
                        (contains_bytes(source, tokens[end].value, "@keyframes") ||
                         contains_bytes(source, tokens[end].value, "animation:") ||
                         contains_bytes(source, tokens[end].value, "transition:")))
                        add_diagnostic(out, SVG_ANIM_DIAG_CSS_ANIMATION,
                                       tokens[end].value.offset);
                    end++;
                }
            }
            bool is_animation = token_name(source, token, "animate") ||
                token_name(source, token, "animateTransform") ||
                token_name(source, token, "set") || token_name(source, token, "animateMotion") ||
                token_name(source, token, "animateColor");
            if (!is_animation) continue;
            if (out->track_count >= SVG_ANIM_MAX_TRACKS) {
                if (error_offset != NULL) *error_offset = token->name.offset;
                svg_anim_document_destroy(out);
                return false;
            }
            size_t parent = SIZE_MAX;
            if (token->depth > 0U) {
                for (size_t candidate = index; candidate > 0U; --candidate) {
                    const svg_xml_token *possible = &tokens[candidate - 1U];
                    if ((possible->kind == SVG_XML_TOKEN_START_ELEMENT ||
                         possible->kind == SVG_XML_TOKEN_EMPTY_ELEMENT) &&
                        possible->depth + 1U == token->depth) {
                        parent = candidate - 1U;
                        break;
                    }
                }
            }
            svg_anim_track track;
            if (!parse_track(source, tokens, token_count, index, parent, out,
                             &track)) {
                free(track.keys);
                free(track.splines);
                free(track.motion_points);
                continue;
            }
            out->tracks[out->track_count++] = track;
        }
    }
    (void)resolve_syncbases(out);
    return true;
}

void svg_anim_document_destroy(svg_anim_document *document)
{
    if (document == NULL) return;
    for (size_t index = 0U; index < document->track_count; ++index) {
        free(document->tracks[index].keys);
        free(document->tracks[index].splines);
        free(document->tracks[index].motion_points);
    }
    free(document->tracks);
    *document = (svg_anim_document){0};
}

#include "animation.h"

#include <math.h>
#include <stdlib.h>
#include <string.h>

static double track_duration(const svg_anim_track *track)
{
    double duration = track->duration_indefinite ? INFINITY :
                      track->duration_seconds;
    if (track->repeat_indefinite && isfinite(duration)) duration = INFINITY;
    else if (isfinite(duration))
        duration *= track->repeat_count;
    if (!track->repeat_duration_indefinite &&
        track->repeat_duration < duration) duration = track->repeat_duration;
    if (!isfinite(duration) || duration > SVG_ANIM_MAX_TIMELINE_SECONDS)
        duration = SVG_ANIM_MAX_TIMELINE_SECONDS;
    return duration;
}

static bool resolve_start(const svg_anim_document *document, size_t index,
                          uint8_t state[SVG_ANIM_MAX_TRACKS],
                          double starts[SVG_ANIM_MAX_TRACKS])
{
    if (index >= document->track_count) return false;
    if (state[index] == 2U) return true;
    if (state[index] == 1U) {
        starts[index] = INFINITY;
        state[index] = 2U;
        return true;
    }
    state[index] = 1U;
    const svg_anim_track *track = &document->tracks[index];
    if (!track->supported || track->begin_indefinite) {
        starts[index] = INFINITY;
    } else if (!track->has_begin_sync) {
        starts[index] = track->begin_offset;
    } else {
        size_t reference = track->begin_sync_track;
        if (reference >= document->track_count ||
            !resolve_start(document, reference, state, starts)) return false;
        double reference_time = starts[reference];
        if (track->begin_sync_end) {
            if (!isfinite(reference_time)) {
                starts[index] = INFINITY;
                state[index] = 2U;
                return true;
            }
            reference_time += track_duration(&document->tracks[reference]);
        }
        starts[index] = reference_time + track->begin_offset;
    }
    if (isfinite(starts[index]) &&
        (starts[index] < 0.0 || starts[index] > SVG_ANIM_MAX_TIMELINE_SECONDS))
        starts[index] = INFINITY;
    state[index] = 2U;
    return true;
}

static double active_duration(const svg_anim_document *document, size_t index,
                              const uint8_t state[SVG_ANIM_MAX_TRACKS],
                              const double starts[SVG_ANIM_MAX_TRACKS])
{
    const svg_anim_track *track = &document->tracks[index];
    double duration = track_duration(track);
    if (track->has_end) {
        double end_time = track->end_seconds;
        if (track->end_is_sync) {
            size_t reference = track->end_sync_track;
            if (reference >= document->track_count || state[reference] != 2U ||
                !isfinite(starts[reference])) return 0.0;
            end_time += starts[reference] +
                        track_duration(&document->tracks[reference]);
        }
        double until_end = end_time - starts[index];
        if (until_end < duration) duration = until_end;
    }
    if (duration < 0.0) return 0.0;
    if (duration > SVG_ANIM_MAX_TIMELINE_SECONDS)
        return SVG_ANIM_MAX_TIMELINE_SECONDS;
    return duration;
}

static double value_distance(const svg_anim_value *left,
                             const svg_anim_value *right)
{
    if (left->kind != right->kind) return 0.0;
    if (left->kind == SVG_ANIM_VALUE_COLOR) {
        double sum = 0.0;
        for (size_t channel = 0U; channel < 4U; ++channel) {
            double delta = (double)right->rgba[channel] - left->rgba[channel];
            sum += delta * delta;
        }
        return sqrt(sum);
    }
    if (left->kind == SVG_ANIM_VALUE_NUMBER) return fabs(right->number[0] - left->number[0]);
    if (left->kind == SVG_ANIM_VALUE_TRANSFORM) {
        double sum = 0.0;
        size_t count = (size_t)left->number[3];
        if (count > 3U) count = 3U;
        for (size_t index = 0U; index < count; ++index) {
            double delta = right->number[index] - left->number[index];
            sum += delta * delta;
        }
        return sqrt(sum);
    }
    return 0.0;
}

static double bezier_coordinate(double t, double p1, double p2)
{
    double inverse = 1.0 - t;
    return 3.0 * inverse * inverse * t * p1 +
           3.0 * inverse * t * t * p2 + t * t * t;
}

static double spline_progress(double progress, const double curve[4])
{
    double low = 0.0, high = 1.0, parameter = progress;
    for (size_t iteration = 0U; iteration < 48U; ++iteration) {
        parameter = (low + high) * 0.5;
        double x = bezier_coordinate(parameter, curve[0], curve[2]);
        if (x < progress) low = parameter;
        else high = parameter;
    }
    return bezier_coordinate(parameter, curve[1], curve[3]);
}

static bool paced_interval(const svg_anim_track *track, double progress,
                           size_t *left, size_t *right,
                           double *local_progress)
{
    double total = 0.0;
    for (size_t index = 0U; index + 1U < track->key_count; ++index)
        total += value_distance(&track->keys[index].value,
                                &track->keys[index + 1U].value);
    if (!(total > 0.0)) {
        *left = 0U;
        *right = track->key_count > 1U ? 1U : 0U;
        *local_progress = progress;
        return true;
    }
    double wanted = progress * total, traversed = 0.0;
    for (size_t index = 0U; index + 1U < track->key_count; ++index) {
        double length = value_distance(&track->keys[index].value,
                                       &track->keys[index + 1U].value);
        if (wanted <= traversed + length || index + 2U == track->key_count) {
            *left = index;
            *right = index + 1U;
            *local_progress = length > 0.0 ?
                (wanted - traversed) / length : 0.0;
            return true;
        }
        traversed += length;
    }
    return false;
}

static bool interpolate(const svg_anim_track *track, double progress,
                        svg_anim_value *out)
{
    if (track->key_count == 0U) return false;
    if (track->key_count == 1U) {
        *out = track->keys[0].value;
        return true;
    }
    if (progress <= 0.0) {
        *out = track->keys[0].value;
        return true;
    }
    if (progress >= 1.0) {
        *out = track->keys[track->key_count - 1U].value;
        return true;
    }
    size_t left = 0U, right = 1U;
    double local = 0.0;
    if (track->calc_mode == SVG_ANIM_CALC_PACED) {
        if (!paced_interval(track, progress, &left, &right, &local)) return false;
    } else {
        while (right + 1U < track->key_count &&
               progress >= track->keys[right].time) {
            left++;
            right++;
        }
        double interval = track->keys[right].time - track->keys[left].time;
        local = interval > 0.0 ?
            (progress - track->keys[left].time) / interval : 0.0;
    }
    if (track->calc_mode == SVG_ANIM_CALC_DISCRETE ||
        track->keys[left].value.kind == SVG_ANIM_VALUE_PATH ||
        track->keys[left].value.kind == SVG_ANIM_VALUE_MOTION) {
        *out = local < 1.0 ? track->keys[left].value : track->keys[right].value;
        return true;
    }
    if (track->calc_mode == SVG_ANIM_CALC_SPLINE && left < track->spline_count)
        local = spline_progress(local, track->splines[left]);
    const svg_anim_value *start = &track->keys[left].value;
    const svg_anim_value *end = &track->keys[right].value;
    if (start->kind != end->kind) return false;
    *out = *start;
    if (start->kind == SVG_ANIM_VALUE_COLOR) {
        for (size_t channel = 0U; channel < 4U; ++channel) {
            double value = (double)start->rgba[channel] +
                ((double)end->rgba[channel] - start->rgba[channel]) * local;
            if (value < 0.0) value = 0.0;
            if (value > 255.0) value = 255.0;
            out->rgba[channel] = (uint8_t)floor(value + 0.5);
        }
        out->raw_offset = 0U;
        out->raw_length = 0U;
        return true;
    }
    if (start->kind == SVG_ANIM_VALUE_NUMBER) {
        out->number[0] = start->number[0] +
            (end->number[0] - start->number[0]) * local;
        return isfinite(out->number[0]);
    }
    if (start->kind == SVG_ANIM_VALUE_TRANSFORM) {
        size_t count = (size_t)start->number[3];
        if (count > 3U || count != (size_t)end->number[3]) return false;
        for (size_t index = 0U; index < count; ++index)
            out->number[index] = start->number[index] +
                (end->number[index] - start->number[index]) * local;
        return true;
    }
    *out = *start;
    return true;
}

static void add_accumulation(const svg_anim_track *track, size_t iteration,
                             svg_anim_value *value)
{
    if (!track->accumulate || iteration == 0U || track->key_count < 2U) return;
    double repeat = (double)iteration;
    const svg_anim_value *first = &track->keys[0].value;
    const svg_anim_value *last = &track->keys[track->key_count - 1U].value;
    if (value->kind == SVG_ANIM_VALUE_NUMBER && first->kind == value->kind &&
        last->kind == value->kind) {
        value->number[0] += repeat * (last->number[0] - first->number[0]);
    } else if (value->kind == SVG_ANIM_VALUE_COLOR && first->kind == value->kind &&
               last->kind == value->kind) {
        for (size_t channel = 0U; channel < 4U; ++channel) {
            double result = value->rgba[channel] + repeat *
                ((double)last->rgba[channel] - first->rgba[channel]);
            if (result < 0.0) result = 0.0;
            if (result > 255.0) result = 255.0;
            value->rgba[channel] = (uint8_t)floor(result + 0.5);
        }
    }
}

static bool motion_at(const svg_anim_track *track, double progress,
                      svg_anim_value *out)
{
    if (track->motion_points == NULL || track->motion_point_count < 2U ||
        !(track->motion_length > 0.0)) return false;
    double wanted = progress * track->motion_length;
    size_t right = 1U;
    while (right + 1U < track->motion_point_count &&
           wanted > track->motion_points[right].distance) right++;
    const svg_anim_motion_point *left_point = &track->motion_points[right - 1U];
    const svg_anim_motion_point *right_point = &track->motion_points[right];
    double segment = right_point->distance - left_point->distance;
    double local = segment > 0.0 ?
        (wanted - left_point->distance) / segment : 0.0;
    if (local < 0.0) local = 0.0;
    if (local > 1.0) local = 1.0;
    *out = (svg_anim_value){.kind = SVG_ANIM_VALUE_MOTION};
    out->number[0] = left_point->x + (right_point->x - left_point->x) * local;
    out->number[1] = left_point->y + (right_point->y - left_point->y) * local;
    if (track->motion_rotate_auto) {
        double angle = atan2(right_point->y - left_point->y,
                             right_point->x - left_point->x) *
                       57.2957795130823208768;
        if (track->motion_rotate_reverse) angle += 180.0;
        out->number[2] = angle;
    } else out->number[2] = track->motion_fixed_rotation;
    out->number[3] = 1.0;
    return isfinite(out->number[0]) && isfinite(out->number[1]) &&
           isfinite(out->number[2]);
}

static bool evaluate_one(const svg_anim_document *document, size_t index,
                         const uint8_t state[SVG_ANIM_MAX_TRACKS],
                         const double starts[SVG_ANIM_MAX_TRACKS], double time,
                         svg_anim_overlay_item *out)
{
    const svg_anim_track *track = &document->tracks[index];
    *out = (svg_anim_overlay_item){.track_index = index};
    if (!track->supported || !isfinite(starts[index]) || time < starts[index]) return true;
    double duration = active_duration(document, index, state, starts);
    double elapsed = time - starts[index];
    bool finished = elapsed >= duration;
    if (finished && track->fill_mode != SVG_ANIM_FILL_FREEZE) return true;
    if (finished) elapsed = duration;
    double progress = 0.0;
    size_t iteration = 0U;
    if (track->kind == SVG_ANIM_KIND_SET || track->duration_indefinite ||
        !(track->duration_seconds > 0.0)) {
        progress = 1.0;
    } else if (finished) {
        double total_repeats = duration / track->duration_seconds;
        double fractional = total_repeats - floor(total_repeats);
        if (fractional > 0.0 && track->fill_mode == SVG_ANIM_FILL_FREEZE) {
            iteration = (size_t)floor(total_repeats);
            progress = fractional;
        } else {
            iteration = total_repeats > 0.0 ?
                        (size_t)floor(total_repeats - 1.0e-12) : 0U;
            progress = 1.0;
        }
    } else {
        iteration = (size_t)floor(elapsed / track->duration_seconds);
        progress = fmod(elapsed, track->duration_seconds) /
                   track->duration_seconds;
    }
    if (track->kind == SVG_ANIM_KIND_MOTION) {
        if (!motion_at(track, progress, &out->value)) return false;
    } else {
        if (!interpolate(track, progress, &out->value)) return false;
        add_accumulation(track, iteration, &out->value);
    }
    if (track->additive_sum && out->value.kind == SVG_ANIM_VALUE_NUMBER &&
        track->base_value.kind == SVG_ANIM_VALUE_NUMBER)
        out->value.number[0] += track->base_value.number[0];
    out->iteration = iteration;
    out->active = true;
    return true;
}

bool svg_anim_eval(const svg_anim_document *document, double time_seconds,
                   svg_anim_overlay *out)
{
    if (out == NULL) return false;
    *out = (svg_anim_overlay){0};
    if (document == NULL || !isfinite(time_seconds) || time_seconds < 0.0 ||
        time_seconds > SVG_ANIM_MAX_TIMELINE_SECONDS ||
        document->track_count > SVG_ANIM_MAX_TRACKS) return false;
    out->time_seconds = time_seconds;
    if (document->track_count == 0U) return true;
    if (document->track_count > SIZE_MAX / sizeof(*out->items)) return false;
    out->items = calloc(document->track_count, sizeof(*out->items));
    if (out->items == NULL) return false;
    out->count = document->track_count;
    uint8_t state[SVG_ANIM_MAX_TRACKS] = {0};
    double starts[SVG_ANIM_MAX_TRACKS] = {0.0};
    for (size_t index = 0U; index < document->track_count; ++index) {
        if (!resolve_start(document, index, state, starts)) {
            svg_anim_overlay_destroy(out);
            return false;
        }
    }
    for (size_t index = 0U; index < document->track_count; ++index) {
        if (!evaluate_one(document, index, state, starts, time_seconds,
                          &out->items[index])) {
            svg_anim_overlay_destroy(out);
            return false;
        }
    }
    return true;
}

void svg_anim_overlay_destroy(svg_anim_overlay *overlay)
{
    if (overlay == NULL) return;
    free(overlay->items);
    *overlay = (svg_anim_overlay){0};
}
#include "animation_internal.h"

#include <errno.h>
#include <math.h>
#include <stdlib.h>
#include <string.h>

#define MOTION_MAX_POINTS 4096U
#define MOTION_MAX_BYTES (64U * 1024U)

typedef struct path_reader {
    base_bytes source;
    size_t cursor;
    size_t end;
} path_reader;

static void skip_path_space(path_reader *reader)
{
    while (reader->cursor < reader->end) {
        uint8_t byte = reader->source.ptr[reader->cursor];
        if (byte != ' ' && byte != '\t' && byte != '\r' && byte != '\n' && byte != ',')
            break;
        reader->cursor++;
    }
}

static bool path_has_number(path_reader *reader)
{
    skip_path_space(reader);
    if (reader->cursor >= reader->end) return false;
    uint8_t byte = reader->source.ptr[reader->cursor];
    return (byte >= '0' && byte <= '9') || byte == '+' || byte == '-' || byte == '.';
}

static bool read_path_number(path_reader *reader, double *out)
{
    skip_path_space(reader);
    size_t start = reader->cursor;
    if (start >= reader->end) return false;
    if (reader->source.ptr[reader->cursor] == '+' ||
        reader->source.ptr[reader->cursor] == '-') reader->cursor++;
    bool digits = false;
    while (reader->cursor < reader->end &&
           reader->source.ptr[reader->cursor] >= '0' &&
           reader->source.ptr[reader->cursor] <= '9') {
        digits = true;
        reader->cursor++;
    }
    if (reader->cursor < reader->end && reader->source.ptr[reader->cursor] == '.') {
        reader->cursor++;
        while (reader->cursor < reader->end &&
               reader->source.ptr[reader->cursor] >= '0' &&
               reader->source.ptr[reader->cursor] <= '9') {
            digits = true;
            reader->cursor++;
        }
    }
    if (!digits) return false;
    if (reader->cursor < reader->end &&
        (reader->source.ptr[reader->cursor] == 'e' ||
         reader->source.ptr[reader->cursor] == 'E')) {
        reader->cursor++;
        if (reader->cursor < reader->end &&
            (reader->source.ptr[reader->cursor] == '+' ||
             reader->source.ptr[reader->cursor] == '-')) reader->cursor++;
        size_t exponent_start = reader->cursor;
        while (reader->cursor < reader->end &&
               reader->source.ptr[reader->cursor] >= '0' &&
               reader->source.ptr[reader->cursor] <= '9') reader->cursor++;
        if (reader->cursor == exponent_start) return false;
    }
    size_t length = reader->cursor - start;
    char buffer[128];
    if (length == 0U || length >= sizeof(buffer)) return false;
    memcpy(buffer, reader->source.ptr + start, length);
    buffer[length] = '\0';
    errno = 0;
    char *end = NULL;
    double value = strtod(buffer, &end);
    if (errno != 0 || end != buffer + length || !isfinite(value) ||
        fabs(value) > 1000000.0) return false;
    *out = value;
    return true;
}

static bool append_motion_point(svg_anim_track *track, size_t *capacity,
                                double x, double y)
{
    if (!isfinite(x) || !isfinite(y) || fabs(x) > 1000000.0 ||
        fabs(y) > 1000000.0 || track->motion_point_count >= MOTION_MAX_POINTS)
        return false;
    if (track->motion_point_count == *capacity) {
        size_t next = *capacity == 0U ? 16U : *capacity * 2U;
        if (next > MOTION_MAX_POINTS) next = MOTION_MAX_POINTS;
        if (next <= *capacity || next > SIZE_MAX / sizeof(*track->motion_points))
            return false;
        svg_anim_motion_point *grown = realloc(track->motion_points,
                                                next * sizeof(*grown));
        if (grown == NULL) return false;
        track->motion_points = grown;
        *capacity = next;
    }
    double distance = 0.0;
    if (track->motion_point_count != 0U) {
        const svg_anim_motion_point *previous =
            &track->motion_points[track->motion_point_count - 1U];
        distance = previous->distance + hypot(x - previous->x, y - previous->y);
        if (!isfinite(distance) || distance > 1000000000.0) return false;
    }
    track->motion_points[track->motion_point_count++] =
        (svg_anim_motion_point){x, y, distance};
    track->motion_length = distance;
    return true;
}

bool svg_anim_parse_motion_path(base_bytes source, svg_xml_span path,
                                svg_anim_track *track)
{
    if (track == NULL || path.length == 0U || path.length > MOTION_MAX_BYTES ||
        path.offset > source.len || path.length > source.len - path.offset) return false;
    path_reader reader = {source, path.offset, path.offset + path.length};
    size_t capacity = 0U;
    double x = 0.0, y = 0.0, start_x = 0.0, start_y = 0.0;
    char command = '\0';
    bool moved = false;
    while (true) {
        skip_path_space(&reader);
        if (reader.cursor == reader.end) break;
        uint8_t byte = source.ptr[reader.cursor];
        if ((byte >= 'A' && byte <= 'Z') || (byte >= 'a' && byte <= 'z')) {
            command = (char)byte;
            reader.cursor++;
            if (command != 'M' && command != 'm' && command != 'L' && command != 'l' &&
                command != 'H' && command != 'h' && command != 'V' && command != 'v' &&
                command != 'Z' && command != 'z') return false;
            if ((command == 'M' || command == 'm') && moved) return false;
            if (command == 'Z' || command == 'z') {
                if (!moved || !append_motion_point(track, &capacity, start_x, start_y))
                    return false;
                x = start_x;
                y = start_y;
                command = '\0';
                continue;
            }
        }
        if (command == '\0' || !path_has_number(&reader)) return false;
        bool relative = command >= 'a' && command <= 'z';
        if (command == 'M' || command == 'm' || command == 'L' || command == 'l') {
            double next_x = 0.0, next_y = 0.0;
            if (!read_path_number(&reader, &next_x) ||
                !read_path_number(&reader, &next_y)) return false;
            if (relative) {
                next_x += x;
                next_y += y;
            }
            x = next_x;
            y = next_y;
            if (!moved) {
                start_x = x;
                start_y = y;
                moved = true;
            }
            if (!append_motion_point(track, &capacity, x, y)) return false;
            if (command == 'M') command = 'L';
            else if (command == 'm') command = 'l';
        } else if (command == 'H' || command == 'h') {
            double next_x = 0.0;
            if (!read_path_number(&reader, &next_x)) return false;
            x = relative ? x + next_x : next_x;
            if (!moved) return false;
            if (!append_motion_point(track, &capacity, x, y)) return false;
        } else if (command == 'V' || command == 'v') {
            double next_y = 0.0;
            if (!read_path_number(&reader, &next_y)) return false;
            y = relative ? y + next_y : next_y;
            if (!moved) return false;
            if (!append_motion_point(track, &capacity, x, y)) return false;
        }
    }
    return moved && track->motion_point_count >= 2U &&
           track->motion_length > 0.0;
}

static bool attr_with_prefix(base_bytes source, const svg_xml_token *tokens,
                             size_t token_count, size_t element,
                             svg_xml_span *out)
{
    for (size_t index = element + 1U;
         index < token_count && tokens[index].kind == SVG_XML_TOKEN_ATTRIBUTE;
         ++index) {
        if (svg_anim_span_eq(source, tokens[index].local_name, "href") &&
            (tokens[index].prefix.length == 0U ||
             svg_anim_span_eq(source, tokens[index].prefix, "xlink"))) {
            *out = tokens[index].value;
            return true;
        }
    }
    return false;
}

static bool same_bytes(base_bytes source, svg_xml_span left,
                       svg_xml_span right)
{
    return left.length != 0U && left.length == right.length &&
        left.offset <= source.len && right.offset <= source.len &&
        left.length <= source.len - left.offset &&
        right.length <= source.len - right.offset &&
        memcmp(source.ptr + left.offset, source.ptr + right.offset,
               left.length) == 0;
}

bool svg_anim_resolve_motion_path(base_bytes source,
                                  const svg_xml_token *tokens,
                                  size_t token_count, size_t animation,
                                  svg_xml_span *out_path)
{
    if (tokens == NULL || out_path == NULL || animation >= token_count) return false;
    if (svg_anim_attr(source, tokens, token_count, animation, "path", out_path))
        return true;
    size_t mpath = SIZE_MAX;
    for (size_t index = animation + 1U; index < token_count; ++index) {
        if (tokens[index].kind == SVG_XML_TOKEN_END_ELEMENT &&
            tokens[index].depth == tokens[animation].depth) break;
        if (tokens[index].depth == tokens[animation].depth + 1U &&
            (tokens[index].kind == SVG_XML_TOKEN_START_ELEMENT ||
             tokens[index].kind == SVG_XML_TOKEN_EMPTY_ELEMENT) &&
            svg_anim_token_name(source, &tokens[index], "mpath")) {
            mpath = index;
            break;
        }
    }
    if (mpath == SIZE_MAX) return false;
    svg_xml_span href = {0U, 0U};
    if (!attr_with_prefix(source, tokens, token_count, mpath, &href) ||
        href.length < 2U || source.ptr[href.offset] != '#') return false;
    svg_xml_span id = {href.offset + 1U, href.length - 1U};
    size_t target = SIZE_MAX, matches = 0U;
    for (size_t index = 0U; index < token_count; ++index) {
        if ((tokens[index].kind != SVG_XML_TOKEN_START_ELEMENT &&
             tokens[index].kind != SVG_XML_TOKEN_EMPTY_ELEMENT) ||
            !svg_anim_token_name(source, &tokens[index], "path")) continue;
        svg_xml_span candidate_id;
        if (svg_anim_attr(source, tokens, token_count, index, "id", &candidate_id) &&
            same_bytes(source, id, candidate_id)) {
            target = index;
            matches++;
        }
    }
    if (matches != 1U) return false;
    return svg_anim_attr(source, tokens, token_count, target, "d", out_path);
}

