 74	    if at.length > 0 && !eq(src, at, b"XML") {
 75	        diagnostic(d, DiagnosticKind::UnsupportedAttribute, at.offset);
 76	        return None;
 77	    }
 78	    let cm = attr0(src, tokens, i, b"calcMode");
 79	    t.calc_mode = match if cm.length == 0 {
 80	        b"linear".as_slice()
 81	    } else {
 82	        span(src, cm)?
 83	    } {
 84	        b"linear" => CalcMode::Linear,
 85	        b"discrete" => CalcMode::Discrete,
 86	        b"spline" => CalcMode::Spline,
 87	        b"paced" => CalcMode::Paced,
 88	        _ => {
 89	            diagnostic(d, DiagnosticKind::UnsupportedAttribute, cm.offset);
 90	            return None;
 91	        }
 92	    };
 93	    let fill = attr0(src, tokens, i, b"fill");
 94	    t.fill_mode = match if fill.length == 0 {
 95	        b"remove".as_slice()
 96	    } else {
 97	        span(src, fill)?
 98	    } {
 99	        b"remove" => FillMode::Remove,
100	        b"freeze" => FillMode::Freeze,
101	        _ => {
102	            diagnostic(d, DiagnosticKind::UnsupportedAttribute, fill.offset);
103	            return None;
104	        }
105	    };
106	    let add = attr0(src, tokens, i, b"additive");
107	    if add.length > 0 && !eq(src, add, b"replace") {
108	        if eq(src, add, b"sum") {
109	            t.additive_sum = true
110	        } else {
111	            diagnostic(d, DiagnosticKind::UnsupportedComposition, add.offset);
112	            return None;
113	        }
114	    }
115	    let acc = attr0(src, tokens, i, b"accumulate");
116	    if acc.length > 0 && !eq(src, acc, b"none") {
117	        if eq(src, acc, b"sum") {
118	            t.accumulate = true
119	        } else {
120	            diagnostic(d, DiagnosticKind::UnsupportedComposition, acc.offset);
121	            return None;
122	        }
123	    }
124	    if (t.kind == Kind::Motion && (t.additive_sum || t.accumulate))
125	        || (t.kind == Kind::Transform && t.accumulate)
126	        || (t.attribute == Attribute::D && (t.additive_sum || t.accumulate))
127	    {
128	        diagnostic(d, DiagnosticKind::UnsupportedComposition, tag.name.offset);
129	        return None;
130	    }
131	    let begin = attr0(src, tokens, i, b"begin");
132	    if begin.length > 0 && !sync_time(src, begin, &mut t, true) {
133	        diagnostic(d, DiagnosticKind::UnsupportedTiming, begin.offset);
134	        return None;
135	    }
136	    let end = attr0(src, tokens, i, b"end");
137	    if end.length > 0 && !sync_time(src, end, &mut t, false) {
138	        diagnostic(d, DiagnosticKind::UnsupportedTiming, end.offset);
139	        return None;
140	    }
141	    let dur = attr0(src, tokens, i, b"dur");
142	    if dur.length == 0 && t.kind != Kind::Set {
143	        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
144	        return None;
145	    }
146	    if eq(src, dur, b"indefinite") {
147	        t.duration_indefinite = true
148	    } else if dur.length > 0 {
149	        t.duration_seconds = match time(src, dur) {
150	            Some(n) => n,
151	            None => {
152	                diagnostic(d, DiagnosticKind::UnsupportedTiming, dur.offset);
153	                return None;
154	            }
155	        }
156	    }
157	    if !t.duration_indefinite && t.kind != Kind::Set && t.duration_seconds <= 0. {
158	        diagnostic(d, DiagnosticKind::InvalidTrack, dur.offset);
159	        return None;
160	    }
161	    if t.kind == Kind::Set && dur.length == 0 {
162	        t.duration_indefinite = true
163	    }
164	    let rep = attr0(src, tokens, i, b"repeatCount");
165	    if eq(src, rep, b"indefinite") {
166	        t.repeat_indefinite = true;
167	        t.repeat_count = f64::INFINITY
168	    } else if rep.length > 0 {
169	        t.repeat_count = match number(src, rep) {
170	            Some(n) if n > 0. && n <= 100000. => n,
171	            _ => {
172	                diagnostic(d, DiagnosticKind::UnsupportedTiming, tag.name.offset);
173	                return None;
174	            }
175	        }
176	    }
177	    if t.kind == Kind::Set {
178	        t.repeat_count = 1.
179	    }
180	    let rd = attr0(src, tokens, i, b"repeatDur");
181	    if eq(src, rd, b"indefinite") {
182	        t.repeat_duration_indefinite = true
183	    } else if rd.length > 0 {
184	        t.repeat_duration = match time(src, rd) {
185	            Some(n) => n,
186	            None => {
187	                diagnostic(d, DiagnosticKind::UnsupportedTiming, rd.offset);
188	                return None;
189	            }
190	        }
191	    }
192	    t.base_value = base_value(src, tokens, parent, t.attribute, t.kind, t.transform_type)?;
193	    let vals = attr0(src, tokens, i, b"values");
194	    let from = attr0(src, tokens, i, b"from");
195	    let to = attr0(src, tokens, i, b"to");
196	    let by = attr0(src, tokens, i, b"by");
197	    if vals.length > 0 && (from.length > 0 || to.length > 0 || by.length > 0) {
198	        diagnostic(d, DiagnosticKind::InvalidTrack, vals.offset);
199	        return None;
200	    }
201	    let mut pieces = Vec::new();
202	    if pieces.try_reserve_exact(MAX_VALUES).is_err() {
203	        *allocation_failed = true;
204	        return None;
205	    }
206	    let mut implicit = false;
207	    let mut by_value = false;
208	    if t.kind == Kind::Motion {
209	        let path = resolve_motion_path(src, tokens, i)
210	            .filter(|p| parse_motion(src, *p, &mut t, allocation_failed));
211	        if path.is_none() {
212	            diagnostic(d, DiagnosticKind::UnsupportedPath, tag.name.offset);
213	            return None;
214	        }
215	        let rot = attr0(src, tokens, i, b"rotate");
216	        if eq(src, rot, b"auto") {
217	            t.motion_rotate_auto = true
218	        } else if eq(src, rot, b"auto-reverse") {
219	            t.motion_rotate_auto = true;
220	            t.motion_rotate_reverse = true
221	        } else if rot.length > 0 {
222	            t.motion_fixed_rotation = match number(src, rot) {
223	                Some(n) => n,
224	                _ => {
225	                    diagnostic(d, DiagnosticKind::UnsupportedAttribute, rot.offset);
226	                    return None;
227	                }
228	            }
229	        }
230	        pieces.push(path.unwrap());
231	    } else if vals.length > 0 {
232	        pieces = match split(src, vals, allocation_failed) {
233	            Some(p) => p,
234	            None => {
235	                diagnostic(d, DiagnosticKind::InvalidTrack, vals.offset);
236	                return None;
237	            }
238	        }
239	    } else if t.kind == Kind::Set {
240	        if to.length == 0 {
241	            diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
242	            return None;
243	        }
244	        pieces.push(to)
245	    } else if from.length > 0 && to.length > 0 {
246	        pieces.extend([from, to])
