248	        implicit = true;
249	        pieces.push(to)
250	    } else if by.length > 0 {
251	        implicit = true;
252	        by_value = true;
253	        pieces.push(by)
254	    } else {
255	        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
256	        return None;
257	    }
258	    if pieces.is_empty() || pieces.len() > MAX_VALUES {
259	        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
260	        return None;
261	    }
262	    let source_count = pieces.len();
263	    if implicit && source_count >= MAX_VALUES {
264	        diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
265	        return None;
266	    }
267	    let count = source_count + usize::from(implicit);
268	    if t.keys.try_reserve_exact(count).is_err() {
269	        *allocation_failed = true;
270	        return None;
271	    }
272	    if implicit {
273	        t.keys.push(Keyframe {
274	            time: 0.,
275	            value: t.base_value,
276	            source: t.base_value.raw,
277	        })
278	    }
279	    for (j, p) in pieces.iter().enumerate() {
280	        let mut v = match parse_value(src, *p, t.attribute, t.kind, t.transform_type) {
281	            Some(v) => v,
282	            None => {
283	                diagnostic(
284	                    d,
285	                    if t.attribute == Attribute::D {
286	                        DiagnosticKind::UnsupportedPath
287	                    } else {
288	                        DiagnosticKind::InvalidTrack
289	                    },
290	                    p.offset,
291	                );
292	                return None;
293	            }
294	        };
295	        if by_value {
296	            if v.kind != ValueKind::Number || t.base_value.kind != ValueKind::Number {
297	                diagnostic(d, DiagnosticKind::UnsupportedComposition, p.offset);
298	                return None;
299	            }
300	            v.number[0] += t.base_value.number[0]
301	        }
302	        let k = j + usize::from(implicit);
303	        t.keys.push(Keyframe {
304	            time: if count == 1 {
305	                0.
306	            } else {
307	                k as f64 / (count - 1) as f64
308	            },
309	            value: v,
310	            source: *p,
311	        })
312	    }
313	    if t.kind == Kind::Animate && t.attribute == Attribute::D {
314	        let base = attr0(src, tokens, parent, b"d");
315	        if base.length == 0 {
316	            diagnostic(d, DiagnosticKind::UnsupportedPath, tag.name.offset);
317	            return None;
318	        }
319	        for key in &t.keys {
320	            if !paths_match(src, base, key.value.raw) {
321	                diagnostic(d, DiagnosticKind::UnsupportedPath, key.value.raw.offset);
322	                return None;
323	            }
324	        }
325	    }
326	    let kt = attr0(src, tokens, i, b"keyTimes");
327	    if kt.length > 0 {
328	        let ts = match split(src, kt, allocation_failed) {
329	            Some(x) => x,
330	            None => {
331	                diagnostic(d, DiagnosticKind::InvalidTrack, kt.offset);
332	                return None;
333	            }
334	        };
335	        if ts.len() != t.keys.len() {
336	            diagnostic(d, DiagnosticKind::InvalidTrack, kt.offset);
337	            return None;
338	        }
339	        let mut prev = -1.;
340	        for (k, s) in t.keys.iter_mut().zip(ts) {
341	            let n = number(src, s).filter(|n| *n >= 0. && *n <= 1. && *n > prev);
342	            if let Some(n) = n {
343	                k.time = n;
344	                prev = n
345	            } else {
346	                diagnostic(d, DiagnosticKind::InvalidTrack, kt.offset);
347	                return None;
348	            }
349	        }
350	        if t.keys[0].time != 0. || (t.kind != Kind::Set && t.keys.last()?.time != 1.) {
351	            diagnostic(d, DiagnosticKind::InvalidTrack, kt.offset);
352	            return None;
353	        }
354	        if t.calc_mode == CalcMode::Paced {
355	            diagnostic(d, DiagnosticKind::UnsupportedAttribute, kt.offset);
356	            return None;
357	        }
358	    }
359	    let spl = attr0(src, tokens, i, b"keySplines");
360	    if t.calc_mode != CalcMode::Spline {
361	        if spl.length > 0 {
362	            diagnostic(d, DiagnosticKind::InvalidTrack, spl.offset);
363	            return None;
364	        }
365	    } else {
366	        let ss = match split(src, spl, allocation_failed) {
367	            Some(x) => x,
368	            None => {
369	                diagnostic(d, DiagnosticKind::InvalidTrack, tag.name.offset);
370	                return None;
371	            }
372	        };
373	        if ss.len() != t.keys.len().saturating_sub(1) {
374	            diagnostic(d, DiagnosticKind::InvalidTrack, spl.offset);
375	            return None;
376	        }
377	        if t.splines.try_reserve_exact(ss.len()).is_err() {
378	            *allocation_failed = true;
379	            return None;
380	        }
381	        for s in ss {
382	            let b = span(src, s)?;
383	            if b.len() >= 256 {
384	                return None;
385	            }
386	            let (vals, count) = number_list(b, 4)?;
387	            if count != 4 || vals.iter().any(|v| !v.is_finite() || *v < 0. || *v > 1.) {
388	                diagnostic(d, DiagnosticKind::InvalidTrack, spl.offset);
389	                return None;
390	            }
391	            t.splines.push([vals[0], vals[1], vals[2], vals[3]])
392	        }
393	    }
394	    Some(t)
395	}
