397	pub fn parse<'a>(source: &'a [u8], tokens: &[XmlToken]) -> Result<Document<'a>, ParseError> {
398	    let mut d = Document {
399	        source,
400	        tracks: Vec::new(),
401	        diagnostics: Vec::new(),
402	    };
403	    d.tracks
404	        .try_reserve_exact(MAX_TRACKS)
405	        .map_err(|_| ParseError::Allocation)?;
406	    d.diagnostics
407	        .try_reserve_exact(MAX_DIAGNOSTICS)
408	        .map_err(|_| ParseError::Allocation)?;
409	    let mut allocation_failed = false;
410	    for (i, t) in tokens.iter().enumerate() {
411	        if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement) {
412	            continue;
413	        }
414	        let name = span(source, t.local_name).unwrap_or_default();
415	        if t.prefix.length == 0 && name == b"style" {
416	            for x in tokens
417	                .iter()
418	                .skip(i + 1)
419	                .take_while(|x| !(x.kind == TokenKind::EndElement && x.depth == t.depth))
420	            {
421	                if x.kind == TokenKind::Text {
422	                    if let Some(b) = span(source, x.value) {
423	                        if [b"@keyframes".as_slice(), b"animation:", b"transition:"]
424	                            .iter()
425	                            .any(|n| b.windows(n.len()).any(|w| w == *n))
426	                        {
427	                            diagnostic(&mut d, DiagnosticKind::CssAnimation, x.value.offset)
428	                        }
429	                    }
430	                }
431	            }
432	        }
433	        if t.prefix.length != 0
434	            || !matches!(
435	                name,
436	                b"animate" | b"animateTransform" | b"set" | b"animateMotion" | b"animateColor"
437	            )
438	        {
439	            continue;
440	        }
441	        if d.tracks.len() >= MAX_TRACKS {
442	            return Err(ParseError::TrackLimit {
443	                offset: t.name.offset,
444	            });
445	        }
446	        let parent = (0..i).rev().find(|&j| {
447	            matches!(
448	                tokens[j].kind,
449	                TokenKind::StartElement | TokenKind::EmptyElement
450	            ) && tokens[j].depth + 1 == t.depth
451	        });
452	        let Some(parent) = parent else {
453	            diagnostic(&mut d, DiagnosticKind::InvalidTrack, t.name.offset);
454	            continue;
455	        };
456	        if let Some(track) = parse_track(source, tokens, i, parent, &mut d, &mut allocation_failed)
457	        {
458	            d.tracks.push(track)
459	        }
460	        if allocation_failed {
461	            return Err(ParseError::Allocation);
462	        }
463	    }
464	    // Resolve syncbase identifiers only after every supported track has been collected.
465	    for i in 0..d.tracks.len() {
466	        for begin in [true, false] {
467	            let id = if begin {
468	                d.tracks[i].begin_sync_id
469	            } else {
470	                d.tracks[i].end_sync_id
471	            };
472	            let Some(id) = id else { continue };
473	            let needle = span(source, id).unwrap_or_default();
474	            let mut found = None;
475	            let mut match_count = 0;
476	            for (j, track) in d.tracks.iter().enumerate() {
477	                if track.id.length > 0 && span(source, track.id) == Some(needle) {
478	                    found = Some(j);
479	                    match_count += 1;
480	                }
481	            }
482	            if match_count != 1 {
483	                diagnostic(&mut d, DiagnosticKind::UnsupportedTiming, id.offset);
484	                d.tracks[i].supported = false
485	            } else if begin {
486	                d.tracks[i].begin_sync_track = found
487	            } else {
488	                d.tracks[i].end_sync_track = found
489	            }
490	        }
491	    }
492	    // Cycles are retained as unsupported timing and resolved by evaluator to inactive tracks.
493	    Ok(d)
494	}
