  7	pub(crate) fn span(source: &[u8], s: XmlSpan) -> Option<&[u8]> {
  8	    s.slice(source)
  9	}
 10	pub(crate) fn eq(source: &[u8], s: XmlSpan, b: &[u8]) -> bool {
 11	    span(source, s) == Some(b)
 12	}
 13	pub(crate) fn attr(source: &[u8], tokens: &[XmlToken], e: usize, name: &[u8]) -> Option<XmlSpan> {
 14	    tokens.get(e)?;
 15	    tokens
 16	        .iter()
 17	        .skip(e + 1)
 18	        .take_while(|a| a.kind == TokenKind::Attribute)
 19	        .find(|a| a.prefix.length == 0 && eq(source, a.local_name, name))
 20	        .map(|a| a.value)
 21	}
 22	pub(crate) fn attr0(source: &[u8], tokens: &[XmlToken], e: usize, name: &[u8]) -> XmlSpan {
 23	    attr(source, tokens, e, name).unwrap_or_default()
 24	}
 25	pub(crate) fn number(source: &[u8], s: XmlSpan) -> Option<f64> {
 26	    let b = span(source, s)?;
 27	    if b.is_empty() || b.len() >= 128 {
 28	        return None;
 29	    }
 30	    let b = b.trim_ascii_start();
 31	    let t = std::str::from_utf8(b).ok()?;
 32	    let n = t.parse::<f64>().ok()?;
 33	    n.is_finite().then_some(n)
 34	}
 35	pub(crate) fn time(source: &[u8], s: XmlSpan) -> Option<f64> {
 36	    let b = span(source, s)?;
 37	    if b.is_empty() || b.len() >= 128 {
 38	        return None;
 39	    }
 40	    let (body, mul) = if b.ends_with(b"ms") {
 41	        (&b[..b.len() - 2], 0.001)
 42	    } else if b.ends_with(b"s") {
 43	        (&b[..b.len() - 1], 1.0)
 44	    } else {
 45	        (b, 1.0)
 46	    };
 47	    let n = std::str::from_utf8(body.trim_ascii_start())
 48	        .ok()?
 49	        .parse::<f64>()
 50	        .ok()?;
 51	    let v = n * mul;
 52	    if n.is_finite() && n >= 0.0 && v.is_finite() && v <= MAX_TIMELINE_SECONDS {
 53	        Some(v)
 54	    } else {
 55	        None
 56	    }
 57	}
 58	pub(crate) fn diagnostic(d: &mut Document<'_>, kind: DiagnosticKind, offset: usize) {
 59	    if d.diagnostics.len() < MAX_DIAGNOSTICS {
 60	        d.diagnostics.push(Diagnostic { kind, offset })
 61	    }
 62	}
 63	pub(crate) fn element_span(tokens: &[XmlToken], i: usize) -> Option<XmlSpan> {
 64	    let start = tokens.get(i)?.source.offset;
 65	    let mut end = start.checked_add(tokens[i].source.length)?;
 66	    if tokens[i].kind == TokenKind::StartElement {
 67	        let depth = tokens[i].depth;
 68	        let close = tokens
 69	            .iter()
 70	            .skip(i + 1)
 71	            .find(|t| t.kind == TokenKind::EndElement && t.depth == depth)?;
 72	        end = close.source.offset.checked_add(close.source.length)?;
 73	    }
 74	    Some(XmlSpan {
 75	        offset: start,
 76	        length: end.checked_sub(start)?,
 77	    })
 78	}
 79	pub(crate) fn attr_kind(source: &[u8], s: XmlSpan) -> (Attribute, bool) {
 80	    let b = span(source, s).unwrap_or_default();
 81	    let a = match b {
 82	        b"x" => Some(Attribute::X),
 83	        b"y" => Some(Attribute::Y),
 84	        b"width" => Some(Attribute::Width),
 85	        b"height" => Some(Attribute::Height),
 86	        b"cx" => Some(Attribute::Cx),
 87	        b"cy" => Some(Attribute::Cy),
 88	        b"r" => Some(Attribute::R),
 89	        b"rx" => Some(Attribute::Rx),
 90	        b"ry" => Some(Attribute::Ry),
 91	        b"opacity" => Some(Attribute::Opacity),
 92	        b"fill-opacity" => Some(Attribute::FillOpacity),
 93	        b"stroke-opacity" => Some(Attribute::StrokeOpacity),
 94	        b"fill" => Some(Attribute::Fill),
 95	        b"stroke" => Some(Attribute::Stroke),
 96	        b"stroke-width" => Some(Attribute::StrokeWidth),
 97	        b"stroke-dashoffset" => Some(Attribute::StrokeDashoffset),
 98	        b"d" => Some(Attribute::D),
 99	        b"transform" => Some(Attribute::Transform),
100	        _ => None,
101	    };
102	    (a.unwrap_or(Attribute::Motion), b == b"transform")
103	}
104	pub(crate) fn color(source: &[u8], s: XmlSpan) -> Option<[u8; 4]> {
105	    let b = span(source, s)?;
106	    if b == b"none" {
107	        return Some([0; 4]);
108	    }
109	    if b.len() == 4 && b[0] == b'#' {
110	        let mut c = [0, 0, 0, 255];
111	        for i in 0..3 {
112	            c[i] = hex(b[i + 1])?.checked_mul(17)?
113	        }
114	        return Some(c);
115	    }
116	    if (b.len() == 7 || b.len() == 9) && b[0] == b'#' {
117	        let mut c = [0, 0, 0, 255];
118	        let n = if b.len() == 9 { 4 } else { 3 };
119	        for i in 0..n {
120	            c[i] = hex(b[1 + i * 2])?
121	                .checked_mul(16)?
122	                .checked_add(hex(b[2 + i * 2])?)?
123	        }
124	        return Some(c);
125	    }
126	    Some(match b {
127	        b"black" => [0, 0, 0, 255],
128	        b"white" => [255, 255, 255, 255],
129	        b"red" => [255, 0, 0, 255],
130	        b"green" => [0, 128, 0, 255],
131	        b"blue" => [0, 0, 255, 255],
132	        b"yellow" => [255, 255, 0, 255],
133	        b"cyan" => [0, 255, 255, 255],
134	        b"magenta" => [255, 0, 255, 255],
135	        b"gray" | b"grey" => [128, 128, 128, 255],
136	        b"transparent" => [0, 0, 0, 0],
137	        _ => return None,
138	    })
139	}
140	pub(crate) fn hex(b: u8) -> Option<u8> {
141	    match b {
142	        b'0'..=b'9' => Some(b - b'0'),
143	        b'a'..=b'f' => Some(b - b'a' + 10),
144	        b'A'..=b'F' => Some(b - b'A' + 10),
145	        _ => None,
146	    }
147	}
148	pub(crate) fn parse_value(
149	    source: &[u8],
150	    s: XmlSpan,
151	    a: Attribute,
152	    k: Kind,
153	    tt: TransformType,
154	) -> Option<Value> {
155	    let mut v = Value {
156	        raw: s,
157	        ..Value::default()
158	    };
159	    if k == Kind::Motion {
160	        v.kind = ValueKind::Motion;
161	        return Some(v);
162	    }
163	    if k == Kind::Transform {
164	        let b = span(source, s)?;
165	        if b.is_empty() || b.len() > 256 {
166	            return None;
167	        }
168	        let (vals, count) = number_list(b, 4)?;
169	        let (min, max) = match tt {
170	            TransformType::Rotate => (1, 3),
171	            TransformType::Translate | TransformType::Scale => (1, 2),
172	            _ => (1, 1),
173	        };
174	        if count < min || count > max {
175	            return None;
176	        }
177	        v.kind = ValueKind::Transform;
178	        v.number[..count].copy_from_slice(&vals[..count]);
179	        v.number[3] = count as f64;
180	        return Some(v);
181	    }
182	    if a == Attribute::D {
183	        v.kind = ValueKind::Path;
184	        return Some(v);
185	    }
186	    if matches!(a, Attribute::Fill | Attribute::Stroke) {
187	        v.kind = ValueKind::Color;
188	        v.rgba = color(source, s)?;
189	        return Some(v);
190	    }
191	    v.kind = ValueKind::Number;
192	    v.number[0] = number(source, s)?;
193	    Some(v)
194	}
195	pub(crate) fn number_list(bytes: &[u8], limit: usize) -> Option<([f64; 4], usize)> {
196	    let mut values = [0.0; 4];
197	    let mut count = 0;
198	    let mut pos = 0;
199	    while pos < bytes.len() {
200	        while bytes
201	            .get(pos)
202	            .is_some_and(|b| b.is_ascii_whitespace() || *b == b',')
203	        {
204	            pos += 1;
205	        }
206	        if pos == bytes.len() {
207	            break;
208	        }
209	        if count >= limit || count >= values.len() {
210	            return None;
211	        }
212	        let start = pos;
213	        if matches!(bytes.get(pos), Some(b'+' | b'-')) {
214	            pos += 1;
215	        }
216	        let mut digits = false;
217	        while bytes.get(pos).is_some_and(u8::is_ascii_digit) {
218	            digits = true;
219	            pos += 1;
220	        }
221	        if bytes.get(pos) == Some(&b'.') {
222	            pos += 1;
223	            while bytes.get(pos).is_some_and(u8::is_ascii_digit) {
224	                digits = true;
225	                pos += 1;
226	            }
227	        }
228	        if !digits {
229	            return None;
230	        }
231	        if matches!(bytes.get(pos), Some(b'e' | b'E')) {
232	            pos += 1;
233	            if matches!(bytes.get(pos), Some(b'+' | b'-')) {
234	                pos += 1;
235	            }
236	            let exp = pos;
237	            while bytes.get(pos).is_some_and(u8::is_ascii_digit) {
238	                pos += 1;
239	            }
240	            if exp == pos {
241	                return None;
242	            }
243	        }
244	        let value = std::str::from_utf8(&bytes[start..pos])
245	            .ok()?
246	            .parse::<f64>()
247	            .ok()?;
248	        if !value.is_finite() {
249	            return None;
250	        }
251	        values[count] = value;
252	        count += 1;
253	    }
254	    Some((values, count))
255	}
256	pub(crate) fn base_value(
257	    source: &[u8],
258	    tokens: &[XmlToken],
259	    target: usize,
260	    a: Attribute,
261	    k: Kind,
262	    tt: TransformType,
263	) -> Option<Value> {
264	    if k == Kind::Transform {
265	        let mut v = Value {
266	            kind: ValueKind::Transform,
267	            ..Value::default()
268	        };
269	        v.number[3] = match tt {
270	            TransformType::Scale => {
271	                v.number[0] = 1.;
272	                v.number[1] = 1.;
273	                2.
274	            }
275	            TransformType::Translate => 2.,
276	            _ => 1.,
277	        };
278	        return Some(v);
279	    }
280	    if k == Kind::Motion {
281	        return Some(Value {
282	            kind: ValueKind::Motion,
283	            ..Value::default()
284	        });
285	    }
286	    let Some(raw) = attr(source, tokens, target, a.name().as_bytes()) else {
287	        let mut v = Value::default();
288	        if matches!(a, Attribute::Fill | Attribute::Stroke) {
289	            v.kind = ValueKind::Color;
290	            if a == Attribute::Fill {
291	                v.rgba[3] = 255
292	            }
293	        } else if matches!(
294	            a,
295	            Attribute::Opacity | Attribute::FillOpacity | Attribute::StrokeOpacity
296	        ) {
297	            v.number[0] = 1.
298	        }
299	        return Some(v);
300	    };
301	    parse_value(source, raw, a, k, tt)
302	}
303	pub(crate) fn split(
304	    source: &[u8],
305	    s: XmlSpan,
306	    allocation_failed: &mut bool,
307	) -> Option<Vec<XmlSpan>> {
308	    let b = span(source, s)?;
309	    let count = b.iter().filter(|&&x| x == b';').count().checked_add(1)?;
310	    if count > MAX_VALUES {
311	        return None;
312	    }
313	    let mut out = Vec::new();
314	    if out.try_reserve_exact(count).is_err() {
315	        *allocation_failed = true;
316	        return None;
317	    }
318	    let mut start = 0;
319	    for i in 0..=b.len() {
320	        if i == b.len() || b[i] == b';' {
321	            let mut a = start;
322	            let mut z = i;
323	            while a < z && b" \t\r\n".contains(&b[a]) {
324	                a += 1
325	            }
326	            while z > a && b" \t\r\n".contains(&b[z - 1]) {
327	                z -= 1
328	            }
329	            if a == z || out.len() >= MAX_VALUES {
330	                return None;
331	            }
332	            out.push(XmlSpan {
333	                offset: s.offset.checked_add(a)?,
334	                length: z - a,
335	            });
336	            start = i.saturating_add(1)
337	        }
338	    }
339	    Some(out)
340	}
341	pub(crate) fn sync_time(src: &[u8], s: XmlSpan, t: &mut Track, is_begin: bool) -> bool {
342	    if eq(src, s, b"indefinite") {
343	        if is_begin {
344	            t.begin_indefinite = true
345	        } else {
346	            t.has_end = false
347	        }
348	        return true;
349	    }
350	    if let Some(v) = time(src, s) {
351	        if is_begin {
352	            t.begin_offset = v
353	        } else {
354	            t.end_seconds = v;
355	            t.has_end = true
356	        }
357	        return true;
358	    }
359	    let Some(b) = span(src, s) else { return false };
360	    let Some(dot) = b.iter().position(|&x| x == b'.') else {
361	        return false;
362	    };
363	    if dot == 0 || dot + 1 >= b.len() {
364	        return false;
365	    }
366	    let suffix_end = (dot + 1..b.len())
367	        .find(|&i| matches!(b[i], b'+' | b'-'))
368	        .unwrap_or(b.len());
369	    let suffix = &b[dot + 1..suffix_end];
370	    let sync_end = match suffix {
371	        b"end" => true,
372	        b"begin" => false,
373	        _ => return false,
374	    };
375	    let mut off = 0.;
376	    if suffix_end < b.len() {
377	        let n = XmlSpan {
378	            offset: s.offset + suffix_end + 1,
379	            length: b.len() - suffix_end - 1,
380	        };
381	        off = match time(src, n) {
382	            Some(n) => n,
383	            None => return false,
384	        };
385	        if b[suffix_end] == b'-' {
386	            off = -off
387	        }
388	    }
389	    let id = XmlSpan {
390	        offset: s.offset,
391	        length: dot,
392	    };
393	    if id.length == 0 {
394	        return false;
395	    }
396	    if is_begin {
397	        t.has_begin_sync = true;
398	        t.begin_sync_end = sync_end;
399	        t.begin_offset = off;
400	        t.begin_sync_id = Some(id)
401	    } else {
402	        t.has_end = true;
403	        t.end_is_sync = true;
404	        t.end_seconds = off;
405	        t.end_sync_id = Some(id)
406	    }
407	    true
408	}
409	pub(crate) fn path_shape(src: &[u8], s: XmlSpan) -> Option<([u8; 1024], usize, usize)> {
410	    let b = span(src, s)?;
411	    if b.is_empty() || b.len() > MAX_PATH_BYTES {
412	        return None;
413	    }
414	    let (mut commands, mut command_count, mut nums, mut i) = ([0; 1024], 0, 0, 0);
415	    while i < b.len() {
416	        let c = b[i];
417	        if c.is_ascii_alphabetic() {
418	            if !b"MmLlHhVvCcSsQqTtAaZz".contains(&c) || command_count >= commands.len() {
419	                return None;
420	            }
421	            commands[command_count] = c;
422	            command_count += 1;
423	            i += 1;
424	            continue;
425	        }
426	        if b" \t\r\n,".contains(&c) {
427	            i += 1;
428	            continue;
429	        }
430	        let start = i;
431	        if matches!(c, b'+' | b'-') {
432	            i += 1
433	        }
434	        let mut digits = false;
435	        while b.get(i).is_some_and(u8::is_ascii_digit) {
436	            i += 1;
437	            digits = true
438	        }
439	        if b.get(i) == Some(&b'.') {
440	            i += 1;
441	            while b.get(i).is_some_and(u8::is_ascii_digit) {
442	                i += 1;
443	                digits = true
444	            }
445	        }
446	        if !digits {
447	            return None;
448	        }
449	        if matches!(b.get(i), Some(b'e' | b'E')) {
450	            i += 1;
451	            if matches!(b.get(i), Some(b'+' | b'-')) {
452	                i += 1
453	            }
454	            let exp = i;
455	            while b.get(i).is_some_and(u8::is_ascii_digit) {
456	                i += 1
457	            }
458	            if i == exp {
459	                return None;
460	            }
461	        }
462	        if i == start {
463	            return None;
464	        }
465	        nums += 1;
466	        if nums > MAX_PATH_NUMBERS {
467	            return None;
468	        }
469	    }
470	    if command_count == 0 {
471	        None
472	    } else {
473	        Some((commands, command_count, nums))
474	    }
475	}
476	pub(crate) fn paths_match(src: &[u8], a: XmlSpan, b: XmlSpan) -> bool {
477	    match (path_shape(src, a), path_shape(src, b)) {
478	        (Some((x, xc, n)), Some((y, yc, m))) => xc == yc && n == m && x[..xc] == y[..yc],
479	        _ => false,
480	    }
481	}

