  3	fn duration(t: &Track) -> f64 {
  4	    let mut d = if t.duration_indefinite {
  5	        f64::INFINITY
  6	    } else {
  7	        t.duration_seconds
  8	    };
  9	    if t.repeat_indefinite && d.is_finite() {
 10	        d = f64::INFINITY
 11	    } else if d.is_finite() {
 12	        d *= t.repeat_count
 13	    }
 14	    if !t.repeat_duration_indefinite && t.repeat_duration < d {
 15	        d = t.repeat_duration
 16	    }
 17	    if !d.is_finite() || d > MAX_TIMELINE_SECONDS {
 18	        MAX_TIMELINE_SECONDS
 19	    } else {
 20	        d
 21	    }
 22	}
 23	fn resolve(
 24	    doc: &Document<'_>,
 25	    i: usize,
 26	    state: &mut [u8; MAX_TRACKS],
 27	    starts: &mut [f64; MAX_TRACKS],
 28	) -> bool {
 29	    if i >= doc.tracks.len() {
 30	        return false;
 31	    }
 32	    if state[i] == 2 {
 33	        return true;
 34	    }
 35	    if state[i] == 1 {
 36	        starts[i] = f64::INFINITY;
 37	        state[i] = 2;
 38	        return true;
 39	    }
 40	    state[i] = 1;
 41	    let t = &doc.tracks[i];
 42	    if !t.supported || t.begin_indefinite {
 43	        starts[i] = f64::INFINITY
 44	    } else if !t.has_begin_sync {
 45	        starts[i] = t.begin_offset
 46	    } else {
 47	        let Some(r) = t.begin_sync_track else {
 48	            starts[i] = f64::INFINITY;
 49	            state[i] = 2;
 50	            return true;
 51	        };
 52	        if !resolve(doc, r, state, starts) {
 53	            return false;
 54	        }
 55	        let mut s = starts[r];
 56	        if t.begin_sync_end {
 57	            if !s.is_finite() {
 58	                starts[i] = f64::INFINITY;
 59	                state[i] = 2;
 60	                return true;
 61	            }
 62	            s += duration(&doc.tracks[r])
 63	        }
 64	        starts[i] = s + t.begin_offset
 65	    }
 66	    if starts[i].is_finite() && (starts[i] < 0. || starts[i] > MAX_TIMELINE_SECONDS) {
 67	        starts[i] = f64::INFINITY
 68	    }
 69	    state[i] = 2;
 70	    true
 71	}
 72	fn active_duration(
 73	    doc: &Document<'_>,
 74	    i: usize,
 75	    state: &[u8; MAX_TRACKS],
 76	    starts: &[f64; MAX_TRACKS],
 77	) -> f64 {
 78	    let t = &doc.tracks[i];
 79	    let mut d = duration(t);
 80	    if t.has_end {
 81	        let mut end = t.end_seconds;
 82	        if t.end_is_sync {
 83	            let Some(r) = t.end_sync_track else { return 0. };
 84	            if r >= doc.tracks.len() || state[r] != 2 || !starts[r].is_finite() {
 85	                return 0.;
 86	            }
 87	            end += starts[r] + duration(&doc.tracks[r])
 88	        }
 89	        let e = end - starts[i];
 90	        if e < d {
 91	            d = e
 92	        }
 93	    }
 94	    if d < 0. {
 95	        0.
 96	    } else {
 97	        d.min(MAX_TIMELINE_SECONDS)
 98	    }
 99	}
100	fn distance(a: Value, b: Value) -> f64 {
101	    if a.kind != b.kind {
102	        return 0.;
103	    }
104	    match a.kind {
105	        ValueKind::Color => a
106	            .rgba
107	            .iter()
108	            .zip(b.rgba)
109	            .map(|(x, y)| (*x as f64 - y as f64).powi(2))
110	            .sum::<f64>()
111	            .sqrt(),
112	        ValueKind::Number => (b.number[0] - a.number[0]).abs(),
113	        ValueKind::Transform => {
114	            let n = (a.number[3] as usize).min(3);
115	            a.number[..n]
116	                .iter()
117	                .zip(&b.number[..n])
118	                .map(|(x, y)| (y - x).powi(2))
119	                .sum::<f64>()
120	                .sqrt()
121	        }
122	        _ => 0.,
123	    }
124	}
125	fn bezier(t: f64, a: f64, b: f64) -> f64 {
126	    let u = 1. - t;
127	    3. * u * u * t * a + 3. * u * t * t * b + t * t * t
128	}
129	fn spline(p: f64, c: [f64; 4]) -> f64 {
130	    let (mut l, mut h) = (0., 1.);
131	    let mut x = p;
132	    for _ in 0..48 {
133	        x = (l + h) * 0.5;
134	        if bezier(x, c[0], c[2]) < p {
135	            l = x
136	        } else {
137	            h = x
138	        }
139	    }
140	    bezier(x, c[1], c[3])
141	}
142	fn interpolate(t: &Track, p: f64) -> Option<Value> {
143	    let n = t.keys.len();
144	    if n == 0 {
145	        return None;
146	    }
147	    if n == 1 {
148	        return Some(t.keys[0].value);
149	    }
150	    if p <= 0. {
151	        return Some(t.keys[0].value);
152	    }
153	    if p >= 1. {
154	        return Some(t.keys[n - 1].value);
155	    }
156	    let (mut l, mut r, mut local) = (0, 1, 0.);
157	    if t.calc_mode == CalcMode::Paced {
158	        let total = (0..n - 1)
159	            .map(|i| distance(t.keys[i].value, t.keys[i + 1].value))
160	            .sum::<f64>();
161	        if total <= 0. {
162	            local = p
163	        } else {
164	            let wanted = p * total;
165	            let mut traversed = 0.;
166	            for i in 0..n - 1 {
167	                let d = distance(t.keys[i].value, t.keys[i + 1].value);
168	                if wanted <= traversed + d || i + 2 == n {
169	                    l = i;
170	                    r = i + 1;
171	                    local = if d > 0. { (wanted - traversed) / d } else { 0. };
172	                    break;
173	                }
174	                traversed += d
175	            }
176	        }
177	    } else {
178	        while r + 1 < n && p >= t.keys[r].time {
179	            l += 1;
180	            r += 1
181	        }
182	        let dt = t.keys[r].time - t.keys[l].time;
183	        local = if dt > 0. {
184	            (p - t.keys[l].time) / dt
185	        } else {
186	            0.
187	        }
188	    }
189	    let a = t.keys[l].value;
190	    let b = t.keys[r].value;
191	    if t.calc_mode == CalcMode::Discrete || matches!(a.kind, ValueKind::Path | ValueKind::Motion) {
192	        return Some(if local < 1. { a } else { b });
193	    }
194	    if t.calc_mode == CalcMode::Spline {
195	        local = spline(local, *t.splines.get(l)?)
196	    }
197	    if a.kind != b.kind {
198	        return None;
199	    }
200	    let mut v = a;
201	    match a.kind {
202	        ValueKind::Color => {
203	            for i in 0..4 {
204	                v.rgba[i] = (a.rgba[i] as f64 + (b.rgba[i] as f64 - a.rgba[i] as f64) * local)
205	                    .clamp(0., 255.)
206	                    .round() as u8
207	            }
208	            v.raw = Default::default()
209	        }
210	        ValueKind::Number => {
211	            v.number[0] = a.number[0] + (b.number[0] - a.number[0]) * local;
212	            if !v.number[0].is_finite() {
213	                return None;
214	            }
215	        }
216	        ValueKind::Transform => {
217	            let count = a.number[3] as usize;
218	            if count > 3 || count != b.number[3] as usize {
219	                return None;
220	            }
221	            for i in 0..count {
222	                v.number[i] = a.number[i] + (b.number[i] - a.number[i]) * local
223	            }
224	        }
225	        _ => (),
226	    }
227	    Some(v)
228	}
229	fn motion(t: &Track, p: f64) -> Option<Value> {
230	    if t.motion_points.len() < 2 || t.motion_length <= 0. {
231	        return None;
232	    }
233	    let wanted = p * t.motion_length;
234	    let mut r = 1;
235	    while r + 1 < t.motion_points.len() && wanted > t.motion_points[r].distance {
236	        r += 1
237	    }
238	    let a = t.motion_points[r - 1];
239	    let b = t.motion_points[r];
240	    let d = b.distance - a.distance;
241	    let q = if d > 0. {
242	        ((wanted - a.distance) / d).clamp(0., 1.)
243	    } else {
244	        0.
245	    };
246	    let mut v = Value {
247	        kind: ValueKind::Motion,
248	        ..Value::default()
249	    };
250	    v.number[0] = a.x + (b.x - a.x) * q;
251	    v.number[1] = a.y + (b.y - a.y) * q;
252	    v.number[2] = if t.motion_rotate_auto {
253	        (b.y - a.y).atan2(b.x - a.x).to_degrees() + if t.motion_rotate_reverse { 180. } else { 0. }
254	    } else {
255	        t.motion_fixed_rotation
256	    };
257	    v.number[3] = 1.;
258	    [v.number[0], v.number[1], v.number[2]]
259	        .iter()
260	        .all(|x| x.is_finite())
261	        .then_some(v)
262	}
263	fn accumulate(t: &Track, iteration: usize, v: &mut Value) {
264	    if !t.accumulate || iteration == 0 || t.keys.len() < 2 {
265	        return;
266	    }
267	    let a = t.keys[0].value;
268	    let b = t.keys[t.keys.len() - 1].value;
269	    match v.kind {
270	        ValueKind::Number if a.kind == v.kind && b.kind == v.kind => {
271	            v.number[0] += iteration as f64 * (b.number[0] - a.number[0])
272	        }
273	        ValueKind::Color if a.kind == v.kind && b.kind == v.kind => {
274	            for c in 0..4 {
275	                v.rgba[c] = (v.rgba[c] as f64
276	                    + iteration as f64 * (b.rgba[c] as f64 - a.rgba[c] as f64))
277	                    .clamp(0., 255.)
278	                    .round() as u8
279	            }
280	        }
281	        _ => (),
282	    }
283	}
