320	            };
321	            (1., iteration)
322	        }
323	    } else {
324	        (
325	            (e % t.duration_seconds) / t.duration_seconds,
326	            (e / t.duration_seconds).floor() as usize,
327	        )
328	    };
329	    let mut value = if t.kind == Kind::Motion {
330	        motion(t, p)?
331	    } else {
332	        let mut v = interpolate(t, p)?;
333	        accumulate(t, it, &mut v);
334	        v
335	    };
336	    if t.additive_sum && value.kind == ValueKind::Number && t.base_value.kind == ValueKind::Number {
337	        value.number[0] += t.base_value.number[0]
338	    }
339	    out.value = value;
340	    out.iteration = it;
341	    out.active = true;
342	    Some(out)
