345	/// Evaluate every parsed track at a finite time in the supported timeline.
346	/// On invalid input or any failed evaluation, no partial overlay is returned.
347	pub fn evaluate(doc: &Document<'_>, time_seconds: f64) -> Option<Overlay> {
348	    if !time_seconds.is_finite()
349	        || !(0.0..=MAX_TIMELINE_SECONDS).contains(&time_seconds)
350	        || doc.tracks.len() > MAX_TRACKS
351	    {
352	        return None;
353	    }
354	    let mut items = Vec::new();
355	    items.try_reserve_exact(doc.tracks.len()).ok()?;
356	    let mut state = [0u8; MAX_TRACKS];
357	    let mut starts = [0.0; MAX_TRACKS];
358	    for i in 0..doc.tracks.len() {
359	        if !resolve(doc, i, &mut state, &mut starts) {
360	            return None;
361	        }
362	    }
363	    for i in 0..doc.tracks.len() {
364	        items.push(one(doc, i, &state, &starts, time_seconds)?)
365	    }
366	    Some(Overlay {
367	        items,
368	        time_seconds,
369	    })
370	}
