  7	pub(crate) fn parse_motion(
  8	    source: &[u8],
  9	    span: XmlSpan,
 10	    track: &mut Track,
 11	    allocation_failed: &mut bool,
 12	) -> bool {
 13	    let Some(path) = span.slice(source) else {
 14	        return false;
 15	    };
 16	    if path.is_empty() || path.len() > MAX_BYTES {
 17	        return false;
 18	    }
 19	    let mut p = PathReader { b: path, pos: 0 };
 20	    let (mut x, mut y, mut sx, mut sy) = (0.0, 0.0, 0.0, 0.0);
 21	    let mut cmd = 0u8;
 22	    let mut moved = false;
 23	    while {
 24	        p.ws();
 25	        p.pos < path.len()
 26	    } {
 27	        let b = path[p.pos];
 28	        if b.is_ascii_alphabetic() {
 29	            cmd = b;
 30	            p.pos += 1;
 31	            if !b"MmLlHhVvZz".contains(&cmd) {
 32	                return false;
 33	            }
 34	            if matches!(cmd, b'M' | b'm') && moved {
 35	                return false;
 36	            }
 37	            if matches!(cmd, b'Z' | b'z') {
 38	                if !moved || !push(track, &mut sx, &mut sy, allocation_failed) {
 39	                    return false;
 40	                }
 41	                x = sx;
 42	                y = sy;
 43	                cmd = 0;
 44	                continue;
 45	            }
 46	        }
 47	        if cmd == 0 || !p.has_num() {
 48	            return false;
 49	        }
 50	        let rel = cmd.is_ascii_lowercase();
 51	        match cmd {
 52	            b'M' | b'm' | b'L' | b'l' => {
 53	                let Some(mut nx) = p.number() else {
 54	                    return false;
 55	                };
 56	                let Some(mut ny) = p.number() else {
 57	                    return false;
 58	                };
 59	                if rel {
 60	                    nx += x;
 61	                    ny += y
 62	                }
 63	                x = nx;
 64	                y = ny;
 65	                if !moved {
 66	                    sx = x;
 67	                    sy = y;
 68	                    moved = true
 69	                }
 70	                if !push_xy(track, x, y, allocation_failed) {
 71	                    return false;
 72	                }
 73	                if cmd == b'M' {
 74	                    cmd = b'L'
 75	                } else if cmd == b'm' {
 76	                    cmd = b'l'
 77	                }
 78	            }
 79	            b'H' | b'h' => {
 80	                let Some(nx) = p.number() else { return false };
 81	                x = if rel { x + nx } else { nx };
 82	                if !moved || !push_xy(track, x, y, allocation_failed) {
 83	                    return false;
 84	                }
 85	            }
 86	            b'V' | b'v' => {
 87	                let Some(ny) = p.number() else { return false };
 88	                y = if rel { y + ny } else { ny };
 89	                if !moved || !push_xy(track, x, y, allocation_failed) {
 90	                    return false;
 91	                }
 92	            }
 93	            _ => return false,
 94	        }
 95	    }
 96	    moved && track.motion_points.len() >= 2 && track.motion_length > 0.0
 97	}
 98	struct PathReader<'a> {
 99	    b: &'a [u8],
100	    pos: usize,
101	}
102	impl PathReader<'_> {
103	    fn ws(&mut self) {
104	        while self
105	            .b
106	            .get(self.pos)
107	            .is_some_and(|b| b" \t\r\n,".contains(b))
108	        {
109	            self.pos += 1
110	        }
111	    }
112	    fn has_num(&mut self) -> bool {
113	        self.ws();
114	        self.b
115	            .get(self.pos)
116	            .is_some_and(|b| b.is_ascii_digit() || matches!(b, b'+' | b'-' | b'.'))
117	    }
118	    fn number(&mut self) -> Option<f64> {
119	        self.ws();
120	        let start = self.pos;
121	        if matches!(self.b.get(self.pos), Some(b'+' | b'-')) {
122	            self.pos += 1
123	        }
124	        let mut digit = false;
125	        while self.b.get(self.pos).is_some_and(u8::is_ascii_digit) {
126	            digit = true;
127	            self.pos += 1
128	        }
129	        if self.b.get(self.pos) == Some(&b'.') {
130	            self.pos += 1;
131	            while self.b.get(self.pos).is_some_and(u8::is_ascii_digit) {
132	                digit = true;
133	                self.pos += 1
134	            }
135	        }
136	        if !digit {
137	            return None;
138	        }
139	        if matches!(self.b.get(self.pos), Some(b'e' | b'E')) {
140	            self.pos += 1;
141	            if matches!(self.b.get(self.pos), Some(b'+' | b'-')) {
142	                self.pos += 1
143	            }
144	            let e = self.pos;
145	            while self.b.get(self.pos).is_some_and(u8::is_ascii_digit) {
146	                self.pos += 1
147	            }
148	            if e == self.pos {
149	                return None;
150	            }
151	        }
152	        if self.pos - start >= 128 {
153	            return None;
154	        }
155	        let n = std::str::from_utf8(&self.b[start..self.pos])
156	            .ok()?
157	            .parse::<f64>()
158	            .ok()?;
159	        if n.is_finite() && n.abs() <= 1_000_000.0 {
160	            Some(n)
161	        } else {
162	            None
163	        }
164	    }
165	}
166	fn push(track: &mut Track, x: &mut f64, y: &mut f64, allocation_failed: &mut bool) -> bool {
167	    push_xy(track, *x, *y, allocation_failed)
168	}
169	fn push_xy(track: &mut Track, x: f64, y: f64, allocation_failed: &mut bool) -> bool {
170	    if !x.is_finite()
171	        || !y.is_finite()
172	        || x.abs() > 1e6
173	        || y.abs() > 1e6
174	        || track.motion_points.len() >= MAX_POINTS
175	    {
176	        return false;
177	    }
178	    let d = track
179	        .motion_points
180	        .last()
181	        .map_or(0.0, |p| p.distance + (x - p.x).hypot(y - p.y));
182	    if !d.is_finite() || d > 1e9 {
183	        return false;
184	    }
185	    if track.motion_points.try_reserve(1).is_err() {
186	        *allocation_failed = true;
187	        return false;
188	    }
189	    track.motion_points.push(MotionPoint { x, y, distance: d });
190	    track.motion_length = d;
191	    true
192	}
