194	pub(crate) fn resolve_motion_path(
195	    source: &[u8],
196	    tokens: &[XmlToken],
197	    animation: usize,
198	) -> Option<XmlSpan> {
199	    if let Some(direct) = attr(source, tokens, animation, b"path") {
200	        return Some(direct);
201	    }
202	    let depth = tokens.get(animation)?.depth;
203	    let mut mp = None;
204	    for (i, t) in tokens.iter().enumerate().skip(animation + 1) {
205	        if t.kind == TokenKind::EndElement && t.depth == depth {
206	            break;
207	        }
208	        if t.depth == depth + 1
209	            && matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement)
210	            && t.prefix.length == 0
211	            && t.local_name.slice(source) == Some(b"mpath")
212	        {
213	            mp = Some(i);
214	            break;
215	        }
216	    }
217	    let m = mp?;
218	    let href = tokens
219	        .iter()
220	        .skip(m + 1)
221	        .take_while(|t| t.kind == TokenKind::Attribute)
222	        .find(|t| {
223	            t.local_name.slice(source) == Some(b"href")
224	                && (t.prefix.length == 0 || t.prefix.slice(source) == Some(b"xlink"))
225	        })?
226	        .value;
227	    let value = href.slice(source)?;
228	    if value.len() < 2 || value[0] != b'#' {
229	        return None;
230	    }
231	    let id = &value[1..];
232	    let mut found = None;
233	    for (i, t) in tokens.iter().enumerate() {
234	        if !matches!(t.kind, TokenKind::StartElement | TokenKind::EmptyElement)
235	            || t.prefix.length != 0
236	            || t.local_name.slice(source) != Some(b"path")
237	        {
238	            continue;
239	        }
240	        if attr(source, tokens, i, b"id").and_then(|s| s.slice(source)) == Some(id) {
241	            if found.is_some() {
242	                return None;
243	            }
244	            found = attr(source, tokens, i, b"d")
245	        }
246	    }
247	    found
248	}
