 30	bool attr(base_bytes source, const svg_xml_token *tokens,
 31	                 size_t token_count, size_t element, const char *name,
 32	                 svg_xml_span *out)
 33	{
 34	    if (element >= token_count) return false;
 35	    for (size_t index = element + 1U;
 36	         index < token_count && tokens[index].kind == SVG_XML_TOKEN_ATTRIBUTE;
 37	         ++index) {
 38	        if (tokens[index].prefix.length == 0U &&
 39	            span_eq(source, tokens[index].local_name, name)) {
 40	            if (out != NULL) *out = tokens[index].value;
 41	            return true;
 42	        }
 43	    }
 44	    return false;
 45	}
