 47	svg_xml_span attr_or_empty(base_bytes source,
 48	                                  const svg_xml_token *tokens,
 49	                                  size_t token_count, size_t element,
 50	                                  const char *name)
 51	{
 52	    svg_xml_span value = {0U, 0U};
 53	    (void)attr(source, tokens, token_count, element, name, &value);
 54	    return value;
 55	}
