 57	bool source_number(base_bytes source, svg_xml_span span, double *out)
 58	{
 59	    char buffer[128];
 60	    if (span.length == 0U || span.length >= sizeof(buffer) ||
 61	        span.offset > source.len || span.length > source.len - span.offset)
 62	        return false;
 63	    memcpy(buffer, source.ptr + span.offset, span.length);
 64	    buffer[span.length] = '\0';
 65	    errno = 0;
 66	    char *end = NULL;
 67	    double number = strtod(buffer, &end);
 68	    if (errno != 0 || end != buffer + span.length || !isfinite(number)) return false;
 69	    *out = number;
 70	    return true;
 71	}
